1	using Guardrails.Core.Execution;
2	using Guardrails.Core.Model;
3	
4	namespace Guardrails.Cli.Ui;
5	
6	/// <summary>
7	/// A decorator <see cref="IRunObserver"/> that keeps the DURING-RUN static log site
8	/// (<c>logs/&lt;runId&gt;/index.html</c> + per-task pages) up to date as the run proceeds (issue #141
9	/// item 2). It WRAPS the real observer (live <see cref="LiveRunObserver"/> or
10	/// <see cref="ConsoleRunObserver"/>), forwards every event verbatim, and AFTER forwarding rewrites
11	/// the site through <see cref="LogSiteRenderer"/>:
12	/// <list type="bullet">
13	///   <item>On <see cref="TaskStarting"/> a task flips pending → running and the index is rewritten —
14	///     a running task links to the LIVE server (a click tails it) when a server is up, else plain text.</item>
15	///   <item>On <see cref="TaskFinished"/> a task flips to its settled status, its static page is written
16	///     (<see cref="LogSiteRenderer.WriteTaskPageIfHasAttempts"/>), and the index is rewritten — a
17	///     settled task with attempts on disk now links to its static page.</item>
18	/// </list>
19	///
20	/// <para>The index always carries the <c>meta refresh</c> (<c>includeRefresh:true</c>) so a
21	/// <c>file://</c> view re-reads it as it is rewritten; the DURABLE final/<c>--export</c> index (no
22	/// refresh, all-static) is written separately by the run's end-of-run path, NOT here.</para>
23	///
24	/// <para>The renderer writes atomically, so a browser never reads a torn file. This decorator's own
25	/// status map is the only shared mutable state, and M4 worker threads call in concurrently, so all
26	/// access to it — and the write that projects from it — is serialised under one lock. Renders are
27	/// best-effort: a render failure (e.g. a transient file lock) is swallowed so a UX nicety never
28	/// flips a task's outcome or aborts the run.</para>
29	/// </summary>
30	public sealed class OnTheFlyLogSiteObserver : IRunObserver
31	{
32	    private readonly IRunObserver _inner;
33	    private readonly string _logsRoot;
34	    private readonly string _runId;
35	    private readonly IReadOnlyList<TaskNode> _tasks;
36	    private readonly IReadOnlyDictionary<string, TaskNode> _tasksById;
37	    private readonly Func<string, string?>? _liveUrlForTask;
38	
39	    // Per-task status word, seeded "pending". Mutated and projected under one lock — events arrive
40	    // from concurrent M4 workers, and the index render reads the whole map, so the two must not race.
41	    private readonly object _gate = new();
42	    private readonly Dictionary<string, string> _statusByTask;
43	
44	    /// <param name="inner">The real observer every event is forwarded to (live or console).</param>
45	    /// <param name="logsRoot">The run's <c>logs/&lt;runId&gt;/</c> tree the site is written into.</param>
46	    /// <param name="runId">The run id (titles the rendered index).</param>
47	    /// <param name="tasks">The plan's tasks, in plan order — the rows of the index.</param>
48	    /// <param name="liveUrlForTask">
49	    /// Resolver mapping a task id to its live-server URL, or null when no server is up. A RUNNING task
50	    /// links to this URL (a click tails it) when non-null; null = the running task is plain text.
51	    /// </param>
52	    public OnTheFlyLogSiteObserver(
53	        IRunObserver inner,
54	        string logsRoot,
55	        string runId,
56	        IReadOnlyList<TaskNode> tasks,
57	        Func<string, string?>? liveUrlForTask)
58	    {
59	        _inner = inner ?? throw new ArgumentNullException(nameof(inner));
60	        _logsRoot = logsRoot;
61	        _runId = runId;
62	        _tasks = tasks;
63	        _tasksById = tasks.ToDictionary(t => t.Id, StringComparer.Ordinal);
64	        _liveUrlForTask = liveUrlForTask;
65	        _statusByTask = tasks.ToDictionary(
66	            t => t.Id, _ => LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Pending), StringComparer.Ordinal);
67	    }
68	
69	    /// <summary>
70	    /// Write the initial all-pending index at run start (every task pending, plain text), so the "all
71	    /// tasks" page exists and is browsable the moment the run begins. Best-effort. Delegates to the
72	    /// static <see cref="WriteInitialIndex(string, string, IReadOnlyList{TaskNode}, Func{string, string?})"/>.
73	    /// </summary>
74	    public void WriteInitialIndex() => WriteInitialIndex(_logsRoot, _runId, _tasks, _liveUrlForTask);
75	
76	    /// <summary>
77	    /// Write the initial all-pending index (every task <c>pending</c>, plain link, with the during-run
78	    /// meta-refresh) WITHOUT an observer instance, so the live path can write it — and print the
79	    /// link to it — BEFORE constructing <see cref="LiveRunObserver"/> (which starts the Spectre
80	    /// <c>AnsiConsole.Live</c> region in its ctor). Any console write into an active Live region
81	    /// corrupts the table, so the initial index + its static-index link must be emitted first (#145
82	    /// Bug 1). Best-effort: a render failure is swallowed (a UX nicety never aborts the run).
83	    /// </summary>
84	    /// <param name="logsRoot">The run's <c>logs/&lt;runId&gt;/</c> tree the index is written into.</param>
85	    /// <param name="runId">The run id (titles the rendered index).</param>
86	    /// <param name="tasks">The plan's tasks, in plan order — the rows of the index.</param>
87	    /// <param name="liveUrlForTask">Unused at the all-pending start (no task is running yet); accepted
88	    /// so the static signature matches the instance's link-resolution surface for callers.</param>
89	    public static void WriteInitialIndex(
90	        string logsRoot,
91	        string runId,
92	        IReadOnlyList<TaskNode> tasks,
93	        Func<string, string?>? liveUrlForTask)
94	    {
95	        _ = liveUrlForTask; // no task is running at the all-pending start, so no live link is resolved yet
96	        string pending = LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Pending);
97	        TryRender(() => LogSiteRenderer.WriteIndex(
98	            logsRoot,
99	            runId,
100	            tasks,
101	            statusResolver: _ => pending,
102	            linkResolver: _ => LogSiteRenderer.IndexLink.Plain,
103	            includeRefresh: true));
104	    }
105	
106	    public void TaskStarting(TaskNode task)
107	    {
108	        _inner.TaskStarting(task);
109	        SetStatus(task.Id, LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Running));
110	        RenderIndex();
111	    }
112	
113	    public void AttemptStarting(TaskNode task, int attempt, int budget) =>
114	        _inner.AttemptStarting(task, attempt, budget);
115	
116	    public void GuardrailFinished(TaskNode task, GuardrailResult result) =>
117	        _inner.GuardrailFinished(task, result);
118	
119	    public void TaskFinished(TaskResult result)
120	    {
121	        _inner.TaskFinished(result);
122	        SetStatus(result.TaskId, StatusWord(result.Outcome));
123	
124	        // Write the finished task's static page so the index's link to it (and the terminal's
125	        // post-mortem link, #141 item 1) resolves to a rendered page, not a 404.
126	        if (_tasksById.TryGetValue(result.TaskId, out TaskNode? task))
127	        {
128	            TryRender(() => LogSiteRenderer.WriteTaskPageIfHasAttempts(_logsRoot, task));
129	        }
130	
131	        RenderIndex();
132	    }
133	
134	    public void PlanHashMismatch(string previousPlanHash) => _inner.PlanHashMismatch(previousPlanHash);
135	
136	    public void ParallelismClampedNoProvider(int requested) => _inner.ParallelismClampedNoProvider(requested);
137	
138	    public void CleanupFailed(string owner, Exception error) => _inner.CleanupFailed(owner, error);
139	
140	    public void PromptPaused(TaskNode task, string reason, TimeSpan backoff, int pauseCount) =>
141	        _inner.PromptPaused(task, reason, backoff, pauseCount);
142	
143	    // --- site projection --------------------------------------------------------------------
144	
145	    private void SetStatus(string taskId, string status)
146	    {
147	        lock (_gate)
148	        {
149	            _statusByTask[taskId] = status;
150	        }
151	    }
152	
153	    /// <summary>
154	    /// Rewrite the during-run index (with refresh) from the current status map. Holds the lock for the
155	    /// whole render so the status snapshot and the link choice are consistent (the renderer writes
156	    /// atomically). The link resolver: a RUNNING task → the live URL when a server is up (else plain),
157	    /// any task with attempts on disk → its static page, anything else → plain text.
158	    /// </summary>
159	    private void RenderIndex()
160	    {
161	        lock (_gate)
162	        {
163	            // Snapshot the statuses inside the lock so the resolver closures read a stable view.
164	            var statuses = new Dictionary<string, string>(_statusByTask, StringComparer.Ordinal);
165	            TryRender(() => LogSiteRenderer.WriteIndex(
166	                _logsRoot,
167	                _runId,
168	                _tasks,
169	                statusResolver: id => statuses.TryGetValue(id, out string? s) ? s : "unknown",
170	                linkResolver: id => ResolveLink(id, statuses),
171	                includeRefresh: true));
172	        }
173	    }
174	
175	    private LogSiteRenderer.IndexLink ResolveLink(string taskId, IReadOnlyDictionary<string, string> statuses)
176	    {
177	        bool running = statuses.TryGetValue(taskId, out string? status) &&
178	                       status == LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Running);
179	
180	        // A running task links to the live server (a click tails it) when one is up; otherwise it is
181	        // plain text (no static page to point at yet).
182	        if (running && _liveUrlForTask?.Invoke(taskId) is { } liveUrl)
183	        {
184	            return LogSiteRenderer.IndexLink.LiveTo(liveUrl);
185	        }
186	
187	        // A task with attempts on disk (running-without-server, or settled) links to its static page;
188	        // a pending/no-attempt task is plain text.
189	        return HasAttempts(taskId) ? LogSiteRenderer.IndexLink.Static : LogSiteRenderer.IndexLink.Plain;
190	    }
191	
192	    private bool HasAttempts(string taskId)
193	    {
194	        string taskDir = Path.Combine(_logsRoot, taskId);
195	        if (!Directory.Exists(taskDir))
196	        {
197	            return false;
198	        }
199	
200	        return Directory.EnumerateDirectories(taskDir)
201	            .Any(d => Path.GetFileName(d).StartsWith("attempt-", StringComparison.Ordinal));
202	    }
203	
204	    /// <summary>Map a finished task's outcome to the index status word (mirrors the journal mapping).</summary>
205	    private static string StatusWord(TaskOutcome outcome) => outcome switch
206	    {
207	        TaskOutcome.Succeeded => LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Succeeded),
208	        TaskOutcome.Skipped => "skipped",
209	        TaskOutcome.Blocked => LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Blocked),
210	        TaskOutcome.Cancelled => "cancelled",
211	        // ActionFailed / GuardrailFailed / InvalidFragment / NeedsHuman are all needs-human terminal.
212	        _ => LogSiteRenderer.StatusText(Core.Journal.TaskStatus.NeedsHuman),
213	    };
214	
215	    /// <summary>
216	    /// Run a render action, swallowing IO failures: the on-the-fly site is a UX nicety and must never
217	    /// flip a task's outcome or abort the run. A transient lock/torn-read is retried by the next event.
218	    /// </summary>
219	    private static void TryRender(Action render)
220	    {
221	        try
222	        {
223	            render();
224	        }
225	        catch (IOException)
226	        {
227	            // best-effort — the next event re-renders
228	        }
229	        catch (UnauthorizedAccessException)
230	        {
231	            // best-effort — never let a logs-tree permission hiccup abort the run
232	        }
233	    }
234	}
