using Guardrails.Core.Execution;
using Guardrails.Core.Model;

namespace Guardrails.Cli.Ui;

/// <summary>
/// A decorator <see cref="IRunObserver"/> that keeps the DURING-RUN static log site
/// (<c>logs/&lt;runId&gt;/index.html</c> + per-task pages) up to date as the run proceeds (issue #141
/// item 2). It WRAPS the real observer (live <see cref="LiveRunObserver"/> or
/// <see cref="ConsoleRunObserver"/>), forwards every event verbatim, and AFTER forwarding rewrites
/// the site through <see cref="LogSiteRenderer"/>:
/// <list type="bullet">
///   <item>On <see cref="TaskStarting"/> a task flips pending → running and the index is rewritten —
///     a running task links to the LIVE server (a click tails it) when a server is up, else plain text.</item>
///   <item>On <see cref="TaskFinished"/> a task flips to its settled status, its static page is written
///     (<see cref="LogSiteRenderer.WriteTaskPageIfHasAttempts"/>), and the index is rewritten — a
///     settled task with attempts on disk now links to its static page.</item>
/// </list>
///
/// <para>The index always carries the <c>meta refresh</c> (<c>includeRefresh:true</c>) so a
/// <c>file://</c> view re-reads it as it is rewritten; the DURABLE final/<c>--export</c> index (no
/// refresh, all-static) is written separately by the run's end-of-run path, NOT here.</para>
///
/// <para>The renderer writes atomically, so a browser never reads a torn file. This decorator's own
/// status map is the only shared mutable state, and M4 worker threads call in concurrently, so all
/// access to it — and the write that projects from it — is serialised under one lock. Renders are
/// best-effort: a render failure (e.g. a transient file lock) is swallowed so a UX nicety never
/// flips a task's outcome or aborts the run.</para>
/// </summary>
public sealed class OnTheFlyLogSiteObserver : IRunObserver
{
    private readonly IRunObserver _inner;
    private readonly string _logsRoot;
    private readonly string _runId;
    private readonly IReadOnlyList<TaskNode> _tasks;
    private readonly IReadOnlyDictionary<string, TaskNode> _tasksById;
    private readonly Func<string, string?>? _liveUrlForTask;

    // Per-task status word, seeded "pending". Mutated and projected under one lock — events arrive
    // from concurrent M4 workers, and the index render reads the whole map, so the two must not race.
    private readonly object _gate = new();
    private readonly Dictionary<string, string> _statusByTask;

    /// <param name="inner">The real observer every event is forwarded to (live or console).</param>
    /// <param name="logsRoot">The run's <c>logs/&lt;runId&gt;/</c> tree the site is written into.</param>
    /// <param name="runId">The run id (titles the rendered index).</param>
    /// <param name="tasks">The plan's tasks, in plan order — the rows of the index.</param>
    /// <param name="liveUrlForTask">
    /// Resolver mapping a task id to its live-server URL, or null when no server is up. A RUNNING task
    /// links to this URL (a click tails it) when non-null; null = the running task is plain text.
    /// </param>
    public OnTheFlyLogSiteObserver(
        IRunObserver inner,
        string logsRoot,
        string runId,
        IReadOnlyList<TaskNode> tasks,
        Func<string, string?>? liveUrlForTask)
    {
        _inner = inner ?? throw new ArgumentNullException(nameof(inner));
        _logsRoot = logsRoot;
        _runId = runId;
        _tasks = tasks;
        _tasksById = tasks.ToDictionary(t => t.Id, StringComparer.Ordinal);
        _liveUrlForTask = liveUrlForTask;
        _statusByTask = tasks.ToDictionary(
            t => t.Id, _ => LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Pending), StringComparer.Ordinal);
    }

    /// <summary>
    /// Write the initial all-pending index at run start (every task pending, plain text), so the "all
    /// tasks" page exists and is browsable the moment the run begins. Best-effort. Delegates to the
    /// static <see cref="WriteInitialIndex(string, string, IReadOnlyList{TaskNode}, Func{string, string?})"/>.
    /// </summary>
    public void WriteInitialIndex() => WriteInitialIndex(_logsRoot, _runId, _tasks, _liveUrlForTask);

    /// <summary>
    /// Write the initial all-pending index (every task <c>pending</c>, plain link, with the during-run
    /// meta-refresh) WITHOUT an observer instance, so the live path can write it — and print the
    /// link to it — BEFORE constructing <see cref="LiveRunObserver"/> (which starts the Spectre
    /// <c>AnsiConsole.Live</c> region in its ctor). Any console write into an active Live region
    /// corrupts the table, so the initial index + its static-index link must be emitted first (#145
    /// Bug 1). Best-effort: a render failure is swallowed (a UX nicety never aborts the run).
    /// </summary>
    /// <param name="logsRoot">The run's <c>logs/&lt;runId&gt;/</c> tree the index is written into.</param>
    /// <param name="runId">The run id (titles the rendered index).</param>
    /// <param name="tasks">The plan's tasks, in plan order — the rows of the index.</param>
    /// <param name="liveUrlForTask">Unused at the all-pending start (no task is running yet); accepted
    /// so the static signature matches the instance's link-resolution surface for callers.</param>
    public static void WriteInitialIndex(
        string logsRoot,
        string runId,
        IReadOnlyList<TaskNode> tasks,
        Func<string, string?>? liveUrlForTask)
    {
        _ = liveUrlForTask; // no task is running at the all-pending start, so no live link is resolved yet
        string pending = LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Pending);
        TryRender(() => LogSiteRenderer.WriteIndex(
            logsRoot,
            runId,
            tasks,
            statusResolver: _ => pending,
            linkResolver: _ => LogSiteRenderer.IndexLink.Plain,
            includeRefresh: true));
    }

    public void TaskStarting(TaskNode task)
    {
        _inner.TaskStarting(task);
        SetStatus(task.Id, LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Running));
        RenderIndex();
    }

    public void AttemptStarting(TaskNode task, int attempt, int budget) =>
        _inner.AttemptStarting(task, attempt, budget);

    public void GuardrailFinished(TaskNode task, GuardrailResult result) =>
        _inner.GuardrailFinished(task, result);

    public void TaskFinished(TaskResult result)
    {
        _inner.TaskFinished(result);
        SetStatus(result.TaskId, StatusWord(result.Outcome));

        // Write the finished task's static page so the index's link to it (and the terminal's
        // post-mortem link, #141 item 1) resolves to a rendered page, not a 404.
        if (_tasksById.TryGetValue(result.TaskId, out TaskNode? task))
        {
            TryRender(() => LogSiteRenderer.WriteTaskPageIfHasAttempts(_logsRoot, task));
        }

        RenderIndex();
    }

    public void PlanHashMismatch(string previousPlanHash) => _inner.PlanHashMismatch(previousPlanHash);

    public void ParallelismClampedNoProvider(int requested) => _inner.ParallelismClampedNoProvider(requested);

    public void CleanupFailed(string owner, Exception error) => _inner.CleanupFailed(owner, error);

    public void PromptPaused(TaskNode task, string reason, TimeSpan backoff, int pauseCount) =>
        _inner.PromptPaused(task, reason, backoff, pauseCount);

    // --- site projection --------------------------------------------------------------------

    private void SetStatus(string taskId, string status)
    {
        lock (_gate)
        {
            _statusByTask[taskId] = status;
        }
    }

    /// <summary>
    /// Rewrite the during-run index (with refresh) from the current status map. Holds the lock for the
    /// whole render so the status snapshot and the link choice are consistent (the renderer writes
    /// atomically). The link resolver: a RUNNING task → the live URL when a server is up (else plain),
    /// any task with attempts on disk → its static page, anything else → plain text.
    /// </summary>
    private void RenderIndex()
    {
        lock (_gate)
        {
            // Snapshot the statuses inside the lock so the resolver closures read a stable view.
            var statuses = new Dictionary<string, string>(_statusByTask, StringComparer.Ordinal);
            TryRender(() => LogSiteRenderer.WriteIndex(
                _logsRoot,
                _runId,
                _tasks,
                statusResolver: id => statuses.TryGetValue(id, out string? s) ? s : "unknown",
                linkResolver: id => ResolveLink(id, statuses),
                includeRefresh: true));
        }
    }

    private LogSiteRenderer.IndexLink ResolveLink(string taskId, IReadOnlyDictionary<string, string> statuses)
    {
        bool running = statuses.TryGetValue(taskId, out string? status) &&
                       status == LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Running);

        // A running task links to the live server (a click tails it) when one is up; otherwise it is
        // plain text (no static page to point at yet).
        if (running && _liveUrlForTask?.Invoke(taskId) is { } liveUrl)
        {
            return LogSiteRenderer.IndexLink.LiveTo(liveUrl);
        }

        // A task with attempts on disk (running-without-server, or settled) links to its static page;
        // a pending/no-attempt task is plain text.
        return HasAttempts(taskId) ? LogSiteRenderer.IndexLink.Static : LogSiteRenderer.IndexLink.Plain;
    }

    private bool HasAttempts(string taskId)
    {
        string taskDir = Path.Combine(_logsRoot, taskId);
        if (!Directory.Exists(taskDir))
        {
            return false;
        }

        return Directory.EnumerateDirectories(taskDir)
            .Any(d => Path.GetFileName(d).StartsWith("attempt-", StringComparison.Ordinal));
    }

    /// <summary>Map a finished task's outcome to the index status word (mirrors the journal mapping).</summary>
    private static string StatusWord(TaskOutcome outcome) => outcome switch
    {
        TaskOutcome.Succeeded => LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Succeeded),
        TaskOutcome.Skipped => "skipped",
        TaskOutcome.Blocked => LogSiteRenderer.StatusText(Core.Journal.TaskStatus.Blocked),
        TaskOutcome.Cancelled => "cancelled",
        // ActionFailed / GuardrailFailed / InvalidFragment / NeedsHuman are all needs-human terminal.
        _ => LogSiteRenderer.StatusText(Core.Journal.TaskStatus.NeedsHuman),
    };

    /// <summary>
    /// Run a render action, swallowing IO failures: the on-the-fly site is a UX nicety and must never
    /// flip a task's outcome or abort the run. A transient lock/torn-read is retried by the next event.
    /// </summary>
    private static void TryRender(Action render)
    {
        try
        {
            render();
        }
        catch (IOException)
        {
            // best-effort — the next event re-renders
        }
        catch (UnauthorizedAccessException)
        {
            // best-effort — never let a logs-tree permission hiccup abort the run
        }
    }
}

using Guardrails.Core.Model;

namespace Guardrails.Core.Execution;

/// <summary>
/// Receives progress events as a run proceeds. Keeps the <see cref="Scheduler"/> and
/// <see cref="TaskExecutor"/> free of any console/UI dependency; the CLI supplies a
/// plain-text or live (Spectre) implementation. Implementations MUST be thread-safe —
/// M4 workers emit events concurrently. A no-op default is available via <see cref="Null"/>.
/// </summary>
public interface IRunObserver
{
    /// <summary>A task is about to run its action.</summary>
    void TaskStarting(TaskNode task);

    /// <summary>
    /// An attempt is starting: <paramref name="attempt"/> of <paramref name="budget"/>
    /// for this run (1-based; budget = 1 + retries).
    /// </summary>
    void AttemptStarting(TaskNode task, int attempt, int budget) { }

    /// <summary>A task finished (succeeded, failed, or was blocked).</summary>
    void TaskFinished(TaskResult result);

    /// <summary>A guardrail finished running.</summary>
    void GuardrailFinished(TaskNode task, GuardrailResult result);

    /// <summary>
    /// The resumed journal's plan hash differs from the current plan's — the manifests
    /// changed since the journal was written. The run continues (SSOT §7); this is a loud
    /// warning, not an error.
    /// </summary>
    void PlanHashMismatch(string previousPlanHash) { }

    /// <summary>
    /// A plan requested <paramref name="requested"/>-way parallelism but no worktree provider
    /// was available, so the scheduler clamped to serial (shared-workspace) execution to avoid
    /// an unsafe shared-workspace race (plan 08 §1 / F7). The run continues serially; this is a
    /// loud demotion notice, not an error. Default no-op so non-CLI observers need not handle it.
    /// </summary>
    void ParallelismClampedNoProvider(int requested) { }

    /// <summary>
    /// A best-effort cleanup operation (a segment-worktree <c>Discard</c> or <c>PruneOrphans</c>)
    /// failed during the M2 end-of-run sweep or a failed-task Discard. <paramref name="owner"/> is
    /// the owning task id (or a sentinel like <c>(prune-orphans)</c>). The run's verdict is
    /// unaffected — a cleanup failure must never flip a green run off-green (plan 08 §D / #126).
    /// Default no-op so non-CLI observers need not handle it.
    /// </summary>
    void CleanupFailed(string owner, Exception error) { }

    /// <summary>
    /// A task's prompt action hit a TRANSIENT, retryable infrastructure condition (an HTTP 429/503/529,
    /// "overloaded", or a usage/session/rate limit) and the harness is PAUSING before re-running the
    /// same attempt — WITHOUT consuming the retry budget (SSOT §9, issue #115). <paramref name="reason"/>
    /// is the operator-facing cause (carrying a reset hint like "resets 11:20am" when one was present),
    /// <paramref name="backoff"/> is how long this pause waits, and <paramref name="pauseCount"/> is the
    /// 1-based pause number for this task. A distinct signal so an operator sees a HEALTHY task waiting
    /// out a rate limit, not a failing one. Default no-op so non-CLI observers need not handle it.
    /// </summary>
    void PromptPaused(TaskNode task, string reason, TimeSpan backoff, int pauseCount) { }

    /// <summary>An observer that does nothing.</summary>
    static IRunObserver Null { get; } = new NullObserver();

    private sealed class NullObserver : IRunObserver
    {
        public void TaskStarting(TaskNode task) { }
        public void TaskFinished(TaskResult result) { }
        public void GuardrailFinished(TaskNode task, GuardrailResult result) { }
        public void PlanHashMismatch(string previousPlanHash) { }
    }
}

using System.Text.Encodings.Web;
using System.Text.Json;

namespace Guardrails.Core.Graph;

/// <summary>
/// Renders the local-viewing companion to <c>diagram.md</c>: a self-contained
/// <c>diagram.html</c> that displays the SAME Mermaid DAG with pan / zoom / fullscreen, so a
/// large task+guardrail graph is actually navigable on disk (GitHub renders <c>diagram.md</c>
/// but offers no navigation). Pure: maps the rendered Mermaid text + its <c>source-sha256</c>
/// to an HTML string with no I/O (issue #33).
/// </summary>
/// <remarks>
/// <para>
/// The Mermaid source is embedded VERBATIM as the text content of a
/// <c>&lt;script type="text/plain"&gt;</c> element and read back via <c>textContent</c> — never
/// interpolated into a JS string. This sidesteps every escaping hazard (a label containing a
/// backtick, <c>${</c>, or a quote cannot break the page), and a <c>&lt;script&gt;</c> element's
/// content is "raw text" so entities are not decoded — the source round-trips byte-for-byte.
/// This is safe because <see cref="MermaidRenderer"/> HTML-escapes every label (so <c>&lt;</c>
/// becomes <c>&amp;lt;</c>), meaning the source can never contain <c>&lt;/script&gt;</c>.
/// </para>
/// <para>
/// The <c>source-sha256</c> provenance comment is emitted as the FIRST line (before
/// <c>&lt;!doctype html&gt;</c>) so the same <c>\A</c>-anchored reader that validates
/// <c>diagram.md</c> validates this file too (<c>graph --check</c>). A comment before the
/// doctype does not trigger quirks mode.
/// </para>
/// <para>
/// The renderer (Mermaid) and pan-zoom library load from a CDN, so the interactive view needs
/// internet the first time. GitHub will not execute the embedded script — this file is the
/// LOCAL artifact; <c>diagram.md</c> remains the portal artifact. Fully offline (inlined assets)
/// is a possible follow-up.
/// </para>
/// <para>
/// <b>Legend overlay.</b> A corner-anchored <c>#legend</c> <c>&lt;div&gt;</c>
/// (<c>position: fixed</c>), mirroring the existing <c>#bar</c>/<c>#hint</c> overlay divs, renders
/// <see cref="MermaidRenderer.LegendMarkdown"/>'s content OUTSIDE the Mermaid SVG. A Mermaid-native
/// legend (a disconnected subgraph of colour-swatch nodes) was prototyped and rendered BROKEN —
/// dagre lays out a disconnected subgraph as a phantom extra "task" overlapping the real DAG — so
/// the overlay div is the only approach that renders correctly. Static HTML, not templated from
/// the Mermaid source, so it carries no bearing on <c>source-sha256</c>.
/// </para>
/// <para>
/// <b>Task-container click target: a POST-RENDER SVG title-band overlay (issue #232/#233
/// superseded, issue #235).</b> A Mermaid <c>click</c> directive never fires on a subgraph/cluster
/// element (upstream limitation; see <see cref="MermaidRenderer"/> remarks), and the first fix
/// attempt — an invisible anchor NODE inside the container — proved useless in practice: dagre
/// sizes and packs it into whatever gap its own layout leaves, which for a content-dense container
/// is a tiny, off-center sliver (measured: 0.44% of the container's area on a real 4-guardrail
/// task). The fix implemented here instead runs AFTER <c>mermaid.render</c> resolves: for every
/// <c>g.cluster</c> element whose id starts with <c>task_</c>, compute a full-width band from the
/// cluster's own bounding box down to just past its <c>.cluster-label</c>'s bottom edge (Mermaid
/// always reserves this header strip above any leaf content, so it is empty BY CONSTRUCTION
/// regardless of how many guardrails/preflights the task has — unlike an interior anchor node) and
/// append a real <c>&lt;a href="..." target="_blank"&gt;&lt;rect fill="transparent"&gt;&lt;/a&gt;</c>
/// spanning it. APPENDED, not inserted first: a cluster's only two original children are its
/// background <c>&lt;rect&gt;</c> then its <c>.cluster-label</c> group, so appending puts the
/// overlay last in paint order (on top, clickable) without moving in front of the label text
/// visually (the rect is transparent) and — because every leaf check node lives in an entirely
/// separate top-level SVG group from its own container's <c>g.cluster</c> — the overlay can never
/// occlude or be occluded by a leaf node's own click target either way. The task→folder-path data
/// this script needs (<see cref="MermaidRenderer.TaskFolderTargets"/>) is embedded as a small JSON
/// object keyed by the SAME container id the Mermaid source uses, in a
/// <c>&lt;script type="application/json"&gt;</c> element read back via <c>textContent</c> (same
/// verbatim/never-interpolated treatment as the Mermaid source itself, immune to the same escaping
/// hazards).
/// </para>
/// <para>
/// <b>Long task-name title wrap-overflow, fixed by widening the label's foreignObject
/// post-render (issue cluster-label-wrap-overflow).</b> Mermaid always wraps a cluster's title
/// <c>&lt;div&gt;</c> to a hardcoded 200px width (the bundled <c>mermaid@11.4.1</c>'s plain
/// flowchart cluster shape never overrides <c>createText</c>'s <c>width = 200</c> default,
/// regardless of the container's own — usually much wider — computed width), and dagre's layout
/// pass reserves the container's header-strip height BEFORE that wrapped height is known, so a
/// long kebab-case task name (hyphens are valid soft line-break points) that wraps to 2+ lines
/// prints past the reserved strip, overlapping the first leaf guardrail/preflight box positioned
/// directly below. No Mermaid config knob avoids this — <c>flowchart.htmlLabels</c> only toggles
/// the html-vs-svg-text label renderer, and 11.4.1 has no documented option for cluster-label
/// wrap width. The fix (the <c>fixWrappedClusterLabels</c> function, run AFTER
/// <c>mermaid.render</c> resolves and BEFORE the title-band overlay above, since the overlay's
/// band height depends on the label's — by then possibly shrunk — bounding box) re-wraps the
/// SAME text at up to the container's own width instead: since the container is normally already
/// wider than 200px, this almost always drops the label to one line, which needs LESS height than
/// the original wrap — never more — so no other node/edge/container ever needs to move. Verified
/// headless against 8+ real plans (40+ long task names): every wrapped case converged to one line
/// with the same healthy gap a never-wrapped label already has, and every already-fits label
/// (including the whole golden <c>hello-guardrails</c> example) was left byte-for-byte unchanged.
/// </para>
/// </remarks>
public static class HtmlDiagramRenderer
{
    /// <summary>
    /// Build the <c>diagram.html</c> document for <paramref name="mermaidSource"/> (the exact
    /// text rendered into <c>diagram.md</c>, including the <c>flowchart TD</c> header and the
    /// cosmetic <c>classDef</c> lines) stamped with <paramref name="sourceHash"/>. <paramref
    /// name="taskFolderTargets"/> is the task-container-id → plan-relative-folder-path map (see
    /// <see cref="MermaidRenderer.TaskFolderTargets"/>) the embedded title-band overlay script uses
    /// to resolve each container's click target (issue #235 — see class remarks).
    /// </summary>
    /// <param name="nodeStatuses">
    /// OPTIONAL live-run status map (issue #219): Mermaid node/container id → one of
    /// <c>"pending"</c>, <c>"running"</c>, <c>"passed"</c>, <c>"failed"</c>, <c>"needs-human"</c>,
    /// keyed by the SAME ids <see cref="MermaidRenderer"/> emits (task containers <c>task_&lt;base&gt;</c>,
    /// preflight/guardrail leaves <c>task_&lt;base&gt;_pf_&lt;n&gt;</c>/<c>task_&lt;base&gt;_gr_&lt;n&gt;</c>,
    /// and the plan-level brackets <c>plan_preflights</c>/<c>plan_guardrails</c>). When non-null the
    /// document additionally carries a per-node status-overlay badge (an animated spinner while
    /// <c>running</c>, a settled check/X/"?" glyph once finished). When <c>null</c> (the static
    /// <c>graph</c> command, which never runs live) the output is byte-identical to the pre-#219
    /// three-argument render.
    /// </param>
    /// <param name="includeRefresh">
    /// INDEPENDENT of the status overlay (mirrors <c>LogSiteRenderer.IndexHtml(..., includeRefresh)</c>):
    /// when <paramref name="nodeStatuses"/> is non-null AND this is <c>true</c> (the default,
    /// the DURING-RUN diagram) a <c>&lt;meta http-equiv="refresh" content="2"&gt;</c> is emitted so a
    /// plain <c>file://</c> view re-reads itself as the run progresses; when <c>false</c> (the FINAL
    /// settled render wired at run-end by <c>06-wire-diagramobserver-into-runcommand</c>) the overlay
    /// is still emitted but the refresh tag is not. Ignored when <paramref name="nodeStatuses"/> is null.
    /// </param>
    public static string Render(
        string mermaidSource, string sourceHash, IReadOnlyDictionary<string, string> taskFolderTargets,
        IReadOnlyDictionary<string, string>? nodeStatuses = null, bool includeRefresh = true)
    {
        ArgumentNullException.ThrowIfNull(mermaidSource);
        ArgumentException.ThrowIfNullOrEmpty(sourceHash);
        ArgumentNullException.ThrowIfNull(taskFolderTargets);

        // Newline-normalize so the file is byte-identical across OSes (mirrors the renderer/hash).
        string source = mermaidSource
            .Replace("\r\n", "\n", StringComparison.Ordinal)
            .Replace("\r", "\n", StringComparison.Ordinal)
            .TrimEnd('\n');

        // Encoder that escapes NOTHING beyond what JSON strictly requires (default System.Text.Json
        // escapes '<', '>', '&', etc. as \uXXXX for HTML safety, which is unnecessary here — the
        // JSON sits inside a <script type="application/json"> element, read back via textContent,
        // exactly like the Mermaid source above — but using the unsafe-relaxed encoder keeps a
        // task-id containing e.g. "&" readable in the raw HTML source without changing behavior).
        string targetsJson = JsonSerializer.Serialize(taskFolderTargets, new JsonSerializerOptions
        {
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
        });

        string html = Template
            .Replace("__SOURCE_SHA256__", sourceHash, StringComparison.Ordinal)
            .Replace("__GRAPH_SOURCE__", source, StringComparison.Ordinal)
            .Replace("__TASK_FOLDER_TARGETS__", targetsJson, StringComparison.Ordinal);

        // Live-run status overlay (issue #219) is OPTIONAL: when nodeStatuses is null (the static
        // `graph` command, which never runs live) the template is emitted UNCHANGED, so the output
        // stays byte-identical to the pre-#219 three-argument render. When provided, inject the
        // per-node status badges + CSS, the node-statuses side-table, and — when includeRefresh — the
        // auto-reload meta tag (see InjectStatusOverlay).
        if (nodeStatuses is not null)
        {
            html = InjectStatusOverlay(html, nodeStatuses, includeRefresh);
        }

        // Normalize the full output — the template raw-string literal (and the injected blocks above)
        // pick up \r\n when the file is checked out with CRLF on Windows; the mermaid source is
        // already normalized above.
        return html
            .Replace("\r\n", "\n", StringComparison.Ordinal)
            .Replace("\r", "\n", StringComparison.Ordinal);
    }

    /// <summary>
    /// Inject the live-run status overlay (issue #219) into the base <paramref name="html"/>: the
    /// per-node status-badge markup + CSS, the <c>#node-statuses</c> JSON side-table, and — when
    /// <paramref name="includeRefresh"/> — the <c>&lt;meta http-equiv="refresh"&gt;</c> auto-reload
    /// tag. Called ONLY on the non-null path (see <see cref="Render"/>), so the static-graph output is
    /// left byte-identical.
    /// </summary>
    /// <remarks>
    /// Mirrors the existing title-band overlay's post-render-script technique: the badges are HTML
    /// overlay <c>&lt;div&gt;</c>s (like <c>#bar</c>/<c>#legend</c>) rendered OUTSIDE the SVG and
    /// anchored to each node's on-screen box via <c>getBoundingClientRect()</c>. Because they live in
    /// screen space rather than inside the SVG, they are re-anchored on every <c>svg-pan-zoom</c>
    /// pan/zoom (wired through the pan-zoom instance's <c>onPan</c>/<c>onZoom</c> callbacks) and on
    /// window resize. A <c>running</c> node shows an animated CSS-<c>@keyframes</c> spinner (no
    /// external image); every other (settled) status shows a static glyph. The auto-reload tag is
    /// INDEPENDENT of the overlay (mirrors <c>LogSiteRenderer.IndexHtml(..., includeRefresh)</c>'s
    /// during-run vs final duality) — present for the during-run diagram, dropped for the final
    /// settled render.
    /// </remarks>
    private static string InjectStatusOverlay(
        string html, IReadOnlyDictionary<string, string> nodeStatuses, bool includeRefresh)
    {
        // Same relaxed-encoder side-table treatment as taskFolderTargets: a JSON object (node id ->
        // status word) read back via textContent from a <script type="application/json"> element.
        string statusesJson = JsonSerializer.Serialize(nodeStatuses, new JsonSerializerOptions
        {
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
        });

        // Auto-reload tag (during-run only) right after the viewport meta in <head>.
        if (includeRefresh)
        {
            html = html.Replace(
                "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">",
                "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n"
                    + "<meta http-equiv=\"refresh\" content=\"2\">",
                StringComparison.Ordinal);
        }

        // Status-badge CSS (spinner @keyframes + per-status colours) just before </style>.
        html = html.Replace(
            "</style>", StatusOverlayStyle + "\n</style>", StringComparison.Ordinal);

        // The node id -> status side-table, mirroring the task-folder-targets side-table, placed just
        // before the svg-pan-zoom script so it is already in the DOM when the module script reads it.
        html = html.Replace(
            "<script src=\"https://cdn.jsdelivr.net/npm/svg-pan-zoom",
            "<script type=\"application/json\" id=\"node-statuses\">" + statusesJson + "</script>\n"
                + "<script src=\"https://cdn.jsdelivr.net/npm/svg-pan-zoom",
            StringComparison.Ordinal);

        // The overlay functions, defined just before `let pz = null;` (module scope, after the graph/
        // targets consts, so they can read #node-statuses and be called from the try block below).
        html = html.Replace(
            "let pz = null;", StatusOverlayScript + "\n\nlet pz = null;", StringComparison.Ordinal);

        // Build the overlay on the SAME SVG mermaid.render just produced, right after the title-band
        // overlay (so it measures the SVG in its final, wrap-corrected shape).
        html = html.Replace(
            "  addTaskContainerOverlays(el);",
            "  addTaskContainerOverlays(el);\n  addStatusOverlays(el);",
            StringComparison.Ordinal);

        // Re-anchor the (screen-space) badges whenever the pan-zoom viewport pans or zooms.
        html = html.Replace(
            "minZoom: 0.1, maxZoom: 20, zoomScaleSensitivity: 0.3 });",
            "minZoom: 0.1, maxZoom: 20, zoomScaleSensitivity: 0.3,\n"
                + "                        onPan: positionStatusBadges, onZoom: positionStatusBadges });",
            StringComparison.Ordinal);

        // ...and on resize, plus one initial placement now that pan-zoom has fit the diagram.
        html = html.Replace(
            "  window.addEventListener('resize', () => { pz.resize(); pz.fit(); pz.center(); });",
            "  window.addEventListener('resize', () => { pz.resize(); pz.fit(); pz.center(); positionStatusBadges(); });\n"
                + "  positionStatusBadges();",
            StringComparison.Ordinal);

        return html;
    }

    // Live-run status-overlay CSS (issue #219), injected before </style> only on the non-null path.
    // The spinner is a pure CSS @keyframes rotation (no external image), inherently distinct from a
    // settled status's static glyph. `.status-<word>` colours mirror the log viewer's status palette.
    private const string StatusOverlayStyle = """

  #status-overlays { position: fixed; inset: 0; pointer-events: none; z-index: 9; }
  .status-badge { position: absolute; box-sizing: border-box; width: 18px; height: 18px;
                  border-radius: 50%; display: flex; align-items: center; justify-content: center;
                  font-size: 12px; font-weight: 700; line-height: 1; color: #0b0f14;
                  border: 1px solid #0b0f14; transform: translate(-50%, -50%); }
  .status-passed { background: #3fb950; }
  .status-failed { background: #f85149; color: #ffffff; }
  .status-needs-human { background: #d29922; }
  .status-pending, .status-blocked, .status-unknown { background: #30363d; color: #8aa0b3; }
  .status-spinner { background: transparent; border: 2px solid #243343; border-top-color: #7fdbff;
                    animation: status-spin 0.8s linear infinite; }
  @keyframes status-spin { to { transform: translate(-50%, -50%) rotate(360deg); } }
""";

    // Live-run status-overlay JavaScript (issue #219), injected before `let pz = null;` only on the
    // non-null path. Corner-anchored HTML badges OUTSIDE the SVG (mirroring the #bar/#legend overlays),
    // one per node id in the embedded #node-statuses side-table, re-anchored on every pan/zoom/resize.
    private const string StatusOverlayScript = """
// --- live per-node status overlay (issue #219) -------------------------------------------------
// Corner-anchored status badges rendered as HTML overlay divs OUTSIDE the SVG (mirrors the #bar /
// #legend overlays), one per node id in the embedded #node-statuses side-table. A "running" node
// gets an animated CSS spinner; every settled status gets a static glyph. Because the badges live in
// screen space (not inside the SVG), they are re-anchored to each node's on-screen box
// (getBoundingClientRect) on every svg-pan-zoom pan / zoom + resize — wired below. Mirrors
// addTaskContainerOverlays' technique: it runs on the SAME SVG mermaid.render just produced.
const nodeStatuses = JSON.parse(document.getElementById('node-statuses').textContent);
let statusBadges = [];

function statusGlyph(status) {
  switch (status) {
    case 'passed': return '✓';       // U+2713 CHECK MARK
    case 'failed': return '✗';       // U+2717 BALLOT X
    case 'needs-human': return '?';
    default: return '·';             // pending / blocked / anything else — a STATIC settled dot, never the spinner
  }
}

// Resolve a status-map id to its SVG element. Task containers and NON-empty plan-level brackets keep
// their raw id on the <g class="cluster">; leaf check nodes (and an EMPTY plan bracket, which Mermaid
// draws as a plain node) are ided "flowchart-<logicalId>-<counter>", so fall back to that prefix.
function findStatusTarget(svgEl, id) {
  return svgEl.querySelector('[id="' + id + '"]')
      || svgEl.querySelector('[id^="flowchart-' + id + '-"]');
}

// Build one badge per status entry into a fixed overlay layer (created once). Each badge stays hidden
// until positionStatusBadges places it, so a badge whose node is off-screen never flashes at (0,0).
function addStatusOverlays(svgEl) {
  let layer = document.getElementById('status-overlays');
  if (!layer) { layer = document.createElement('div'); layer.id = 'status-overlays'; document.body.appendChild(layer); }
  layer.innerHTML = '';
  statusBadges = [];
  for (const [id, status] of Object.entries(nodeStatuses)) {
    const target = findStatusTarget(svgEl, id);
    if (!target) continue; // id not present in this render — no badge (defensive)
    const badge = document.createElement('div');
    if (status === 'running') {
      badge.className = 'status-badge status-spinner';
    } else {
      badge.className = 'status-badge status-' + status;
      badge.textContent = statusGlyph(status);
    }
    badge.setAttribute('aria-label', id + ': ' + status);
    badge.style.display = 'none';
    layer.appendChild(badge);
    statusBadges.push({ el: badge, target: target });
  }
  positionStatusBadges();
}

// Re-anchor every badge to the top-right corner of its node's CURRENT on-screen box. Called after the
// overlay is built and again on every pan / zoom / resize so the badges track the diagram exactly.
function positionStatusBadges() {
  for (const b of statusBadges) {
    const r = b.target.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) { b.el.style.display = 'none'; continue; }
    b.el.style.display = '';
    b.el.style.left = r.right + 'px';
    b.el.style.top = r.top + 'px';
  }
}
""";

    // __SOURCE_SHA256__ is filled with a lowercase-hex hash (no escaping needed). __GRAPH_SOURCE__
    // is filled with the verbatim Mermaid text inside a raw-text <script> element (see remarks).
    // __TASK_FOLDER_TARGETS__ is filled with a JSON object (container id -> folder path).
    private const string Template = """
<!-- guardrails:graph v1 source-sha256=__SOURCE_SHA256__ -->
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Guardrails — task/guardrail DAG</title>
<style>
  html, body { margin: 0; height: 100%; background: #0b0f14; color: #d6deeb;
               font-family: system-ui, sans-serif; overflow: hidden; }
  #bar { position: fixed; top: 8px; left: 8px; z-index: 10; display: flex; gap: 6px; }
  #bar button { background: #121a24; color: #d6deeb; border: 1px solid #243343;
                border-radius: 6px; padding: 6px 10px; cursor: pointer; font-size: 13px; }
  #bar button:hover { border-color: #7fdbff; }
  #stage { width: 100vw; height: 100vh; }
  #stage svg { width: 100vw; height: 100vh; max-width: none !important; }
  #hint { position: fixed; bottom: 8px; left: 8px; color: #5b6b7b; font-size: 12px;
          max-width: 90vw; }
  #legend { position: fixed; top: 8px; right: 8px; z-index: 10; background: #121a24;
            border: 1px solid #243343; border-radius: 6px; padding: 8px 12px;
            font-size: 12px; line-height: 1.5; max-width: 340px; }
  #legend .swatch { display: inline-block; width: 10px; height: 10px; border-radius: 2px;
                    margin-right: 6px; }
</style>
</head>
<body>
<div id="bar">
  <button id="fit">Fit</button>
  <button id="zin">+</button>
  <button id="zout">&minus;</button>
  <button id="fs">Fullscreen</button>
</div>
<div id="stage"></div>
<div id="legend">
  <div><span class="swatch" style="background:#e6d7ff;border:1px solid #6f42c1;"></span>
    <b>Preflight</b> &mdash; verified BEFORE the task's attempt loop; gates entry
    (dependency-delivery precondition)</div>
  <div><span class="swatch" style="background:#fff3cd;border:1px solid #b8860b;"></span>
    <b>Guardrail</b> &mdash; verified AFTER the task's action; must pass for the task to finish</div>
  <div><span class="swatch" style="background:#d4edda;border:1px solid #2e7d32;"></span>
    Plan-level containers ("Full Flight Checks" top, "Terminal Gate" bottom) run the same two
    checks once for the whole plan, at the very start and very end.</div>
</div>
<div id="hint">scroll = zoom &middot; drag = pan &middot; Fit resets &middot; Fullscreen (or press F11).
  Node clicks open source files &mdash; serve via a local HTTP server (e.g.
  <code>python -m http.server</code>) for clicks to work; browsers block
  <code>file://&rarr;file://</code> navigation by default.
  On GitHub, diagram.md renders instead.</div>

<script type="text/plain" id="graph-source">__GRAPH_SOURCE__</script>
<script type="application/json" id="task-folder-targets">__TASK_FOLDER_TARGETS__</script>
<script src="https://cdn.jsdelivr.net/npm/svg-pan-zoom@3.6.1/dist/svg-pan-zoom.min.js"></script>
<script type="module">
import mermaid from 'https://cdn.jsdelivr.net/npm/mermaid@11.4.1/dist/mermaid.esm.min.mjs';

const graph = document.getElementById('graph-source').textContent;
const taskFolderTargets = JSON.parse(document.getElementById('task-folder-targets').textContent);
// securityLevel 'loose' is required for the `click ... href` directives to open node sources;
// the content is the user's own local plan, served from file:// — not untrusted input.
// maxTextSize raises Mermaid's default 50 000-character source ceiling (issue #108): a large
// plan's DAG source easily exceeds it, and on overflow mermaid.render throws "Maximum text size
// in diagram exceeded" — landing every big plan in the catch-block "could not render" fallback.
// 5 000 000 covers DAGs far larger than any hand-reviewed plan while still bounding the parser.
// maxEdges raises Mermaid's default 500-edge ceiling for the same reason: a many-task plan fans
// out task→guardrail→done→dependent edges well past 500, and overflow throws "Maximum number of
// edges exceeded". Both ceilings must be lifted or a big plan still fails to render.
mermaid.initialize({ startOnLoad: false, theme: 'dark', securityLevel: 'loose', maxTextSize: 5000000, maxEdges: 100000, flowchart: { useMaxWidth: false } });

// Widen a wrapped cluster-title's foreignObject so a long kebab-case task name reflows onto
// FEWER lines instead of overflowing Mermaid's fixed header-strip reservation (issue
// cluster-label-wrap-overflow). Root cause, confirmed against the bundled mermaid@11.4.1 source
// (`src/rendering-util/createText.ts`'s `createText(el, text, { width = 200 })` default, which
// the plain flowchart "rect" cluster shape never overrides): a cluster's title <div> is always
// wrapped to a hardcoded 200px width regardless of the container's own — usually much wider —
// computed width, and dagre's LAYOUT PASS reserves header space for the container BEFORE that
// wrapped height is known, so it never grows to fit more than a couple of lines. A short label
// fits on one line inside 200px with room to spare (a healthy ~13px gap above the first leaf
// node, measured); a long name (hyphens are valid soft line-break points) wraps to 2 or more
// lines, and each line beyond the first prints a full line-height PAST what dagre reserved —
// landing on top of the first leaf guardrail/preflight box positioned directly below.
//
// Two Mermaid config knobs were checked and ruled out first: `flowchart.htmlLabels` only toggles
// the html-vs-svg-text label renderer (not label width), and 11.4.1 has no documented
// `flowchart`/theme-variable option for cluster-label wrapping width — 200 is a hardcoded
// parameter default the cluster-shape renderer never overrides, not a configurable value.
//
// The fix instead re-wraps the SAME text into fewer lines post-render: a task container is
// normally already wider than 200px (dagre sized it to fit its leaf content), so letting the
// identical label reflow at (up to) the container's own width almost always drops it to one
// line, which needs LESS height than Mermaid's original wrap — never more. That means this can
// only ever shrink the label's footprint, never grow it, so no other node/edge/container ever
// needs to move to make room. Verified headless against 8+ real plans (40+ long task names,
// container widths from ~230px to ~1100px, wraps from 2 to 3 lines): every case converged to one
// line with the same healthy negative gap a short, never-wrapped label already has; every
// already-fits-on-one-line label (including every task in the golden `hello-guardrails` example)
// was left byte-for-byte unchanged.
function fixWrappedClusterLabels(svgEl) {
  const clusters = svgEl.querySelectorAll('g.cluster');
  for (const cluster of clusters) {
    const label = cluster.querySelector('.cluster-label');
    if (!label) continue;
    const fo = label.querySelector('foreignObject');
    const div = fo ? fo.querySelector('div') : null;
    if (!fo || !div) continue;

    const currentWidth = parseFloat(fo.getAttribute('width')) || 0;
    const currentHeight = parseFloat(fo.getAttribute('height')) || 0;
    if (currentWidth <= 0 || currentHeight <= 0) continue;

    // scrollWidth/scrollHeight are LOCAL layout-box measurements in the foreignObject's own
    // SVG-user-unit coordinate system — deliberately NOT the screen-space rect API (see class
    // remarks): a screen-space read is affected by every ancestor SVG transform (dagre's per-node
    // translate, the pan-zoom viewport's zoom/pan matrix), so it would be misleading compared
    // against the foreignObject's own width/height attributes. Measure the label's natural
    // single-line width by temporarily lifting the wrap constraint Mermaid applied, then restore
    // it immediately.
    const savedInline = div.getAttribute('style');
    div.style.whiteSpace = 'nowrap';
    div.style.width = 'auto';
    div.style.maxWidth = 'none';
    // +2px safety buffer: scrollWidth can round down a hair short of the true subpixel width
    // needed for one line (observed empirically — re-applying the exact measured value as a
    // fixed width sometimes still wrapped to 2 lines by a fraction of a pixel).
    const naturalWidth = div.scrollWidth + 2;
    div.setAttribute('style', savedInline); // restore Mermaid's original wrapped styling

    if (naturalWidth <= currentWidth) continue; // already fits on one line — untouched

    // Never widen past the cluster's own body (leave a small margin) — the container's leaf
    // content already determined this width, so the label can use up to it without ever moving
    // a leaf node, edge, or sibling container. Never NARROWER than Mermaid's original width either
    // — this only ever grows the box.
    const clusterBox = cluster.getBBox();
    const newWidth = Math.min(naturalWidth, Math.max(currentWidth, clusterBox.width - 16));

    div.style.whiteSpace = 'break-spaces';
    div.style.display = 'table';
    div.style.width = newWidth + 'px';
    div.style.maxWidth = newWidth + 'px';
    const newHeight = div.scrollHeight;

    if (newHeight >= currentHeight) {
      // Widening did not actually reduce the wrapped height (the cluster is too narrow to fit
      // even one more character per line) — revert rather than risk an oddly-proportioned label.
      div.setAttribute('style', savedInline);
      continue;
    }

    fo.setAttribute('width', String(newWidth));
    fo.setAttribute('height', String(newHeight));

    // Mermaid centers the label group on the cluster's horizontal midpoint via
    // `translate(x - bbox.width / 2, y)`; widening the box without re-centering would shift it
    // left of center, so shift the existing translate by half the width delta to keep it on the
    // SAME midpoint. The label's y stays fixed — only its height shrank, so its bottom edge
    // simply moves UP, further from the first leaf node, never displacing it.
    const transform = label.getAttribute('transform') || '';
    const match = transform.match(/translate\(([-\d.eE]+)\s*,\s*([-\d.eE]+)\)/);
    if (match) {
      const oldX = parseFloat(match[1]);
      const deltaCenter = (newWidth - currentWidth) / 2;
      label.setAttribute('transform', `translate(${oldX - deltaCenter}, ${match[2]})`);
    }
  }
}

// Inject a real clickable overlay on each task container's TITLE/LABEL ROW (issue #232/#233
// superseded, issue #235). Mermaid never fires a `click` directive on a subgraph/cluster element,
// and an anchor NODE inside the container gets packed into whatever sliver of space dagre's own
// layout leaves — useless for a content-dense container. The title band is different: Mermaid
// ALWAYS renders a cluster as exactly two children, a background <rect> then a <g
// class="cluster-label">, with the label in its own reserved header strip above any leaf content —
// so a full-width band from the cluster's top down to just past the label's bottom edge is empty BY
// CONSTRUCTION, regardless of how many guardrails/preflights the task has. Must run AFTER
// fixWrappedClusterLabels (above): the band height is measured from the label's CURRENT bbox, so
// a label that fixWrappedClusterLabels already shrank back to one line gets a correspondingly
// short band, not one sized for its original (possibly multi-line) wrap.
function addTaskContainerOverlays(svgEl) {
  const ns = 'http://www.w3.org/2000/svg';
  const clusters = svgEl.querySelectorAll('g.cluster');
  for (const cluster of clusters) {
    const target = taskFolderTargets[cluster.id];
    if (!target) continue; // not a task container (e.g. plan_preflights/plan_guardrails), or no map entry
    const label = cluster.querySelector('.cluster-label');
    if (!label) continue;

    const clusterBox = cluster.getBBox();
    const labelBox = label.getBBox();
    const bandHeight = (labelBox.y + labelBox.height) - clusterBox.y + 8; // small padding below the title

    const a = document.createElementNS(ns, 'a');
    a.setAttribute('href', target);
    a.setAttribute('target', '_blank');
    a.setAttribute('aria-label', 'Open task folder: ' + target);

    const rect = document.createElementNS(ns, 'rect');
    rect.setAttribute('x', String(clusterBox.x));
    rect.setAttribute('y', String(clusterBox.y));
    rect.setAttribute('width', String(clusterBox.width));
    rect.setAttribute('height', String(bandHeight));
    // Inline style (not the `fill` ATTRIBUTE) deliberately: Mermaid's own generated stylesheet
    // carries a rule like `#dag .cluster rect{fill:<theme color>;...}` that colors every cluster's
    // background rect. Since this overlay rect is nested inside the .cluster group (so it stays in
    // the same paint context as the background rect it sits atop), that same selector matches it
    // too — and a CSS class/tag selector beats a plain presentation attribute, so `fill="transparent"`
    // as an attribute got silently overridden, painting a solid theme-colored bar over the title text.
    // An inline style wins over any external/embedded stylesheet rule (short of `!important`), so it
    // reliably stays invisible regardless of Mermaid's theme.
    rect.style.fill = 'transparent';
    rect.style.cursor = 'pointer';

    a.appendChild(rect);
    // Append as the LAST child — do NOT prepend as the first child. A cluster's only two original
    // children are its background <rect> then its .cluster-label group (in that paint order).
    // Appending puts the overlay on top of the background rect (so it is actually clickable)
    // without covering the label text visually (the rect is transparent either way) — prepending
    // instead would put the overlay BEHIND the background rect (which becomes second-in-order and
    // paints over it), silently blocking every click.
    cluster.appendChild(a);
  }
}

let pz = null;
try {
  const { svg } = await mermaid.render('dag', graph);
  document.getElementById('stage').innerHTML = svg;
  const el = document.querySelector('#stage svg');
  el.setAttribute('width', '100vw');
  el.setAttribute('height', '100vh');
  fixWrappedClusterLabels(el);
  addTaskContainerOverlays(el);
  pz = svgPanZoom(el, { zoomEnabled: true, controlIconsEnabled: false, fit: true, center: true,
                        minZoom: 0.1, maxZoom: 20, zoomScaleSensitivity: 0.3 });
  window.addEventListener('resize', () => { pz.resize(); pz.fit(); pz.center(); });
} catch (e) {
  // Surface the actual failure (offline CDN, or a Mermaid limit we have not yet lifted) instead of
  // guessing — a generic "offline?" message sent every big-plan #108 failure down the wrong path.
  const detail = (e && e.message) ? String(e.message) : String(e);
  const p = document.createElement('p');
  p.style.padding = '1rem';
  p.textContent = 'Could not render the diagram: ' + detail +
    ' — the DAG source is embedded in this page, and diagram.md renders on GitHub.';
  const stage = document.getElementById('stage');
  stage.innerHTML = '';
  stage.appendChild(p);
}

document.getElementById('fit').onclick  = () => { if (pz) { pz.fit(); pz.center(); } };
document.getElementById('zin').onclick  = () => { if (pz) pz.zoomBy(1.3); };
document.getElementById('zout').onclick = () => { if (pz) pz.zoomBy(0.77); };
document.getElementById('fs').onclick   = () => document.documentElement.requestFullscreen();
</script>
</body>
</html>
""";
}

namespace Guardrails.Core.Model;

/// <summary>
/// A single task in the plan DAG. SSOT §3. The task id is its folder name.
/// </summary>
public sealed record TaskNode
{
    /// <summary>Task id = the task folder name (kebab-case, e.g. "01-write-greeting-script").</summary>
    public required string Id { get; init; }

    /// <summary>
    /// Optional stable identity that survives renumbering/slug edits across regenerations
    /// (SSOT §11 / issue #5). Null when the plan does not declare one. Reserved for the
    /// regeneration merge; not yet consumed at runtime.
    /// </summary>
    public string? StableId { get; init; }

    /// <summary>Absolute path to the task folder.</summary>
    public required string Directory { get; init; }

    /// <summary>Required one-line human description (used in feedback and reporting).</summary>
    public required string Description { get; init; }

    /// <summary>Task ids this task depends on. May be empty; never null.</summary>
    public IReadOnlyList<string> DependsOn { get; init; } = [];

    /// <summary>Retry override; null = use <c>defaultRetries</c>. (Retries are M4; carried for fidelity.)</summary>
    public int? Retries { get; init; }

    /// <summary>Whole-attempt timeout ceiling in seconds; null = use <c>defaultTimeoutSeconds</c>.</summary>
    public int? TimeoutSeconds { get; init; }

    /// <summary>The resolved action for this task.</summary>
    public required ActionDefinition Action { get; init; }

    /// <summary>The resolved guardrails, in filename sort order. At least one (validated).</summary>
    public required IReadOnlyList<GuardrailDefinition> Guardrails { get; init; }

    /// <summary>
    /// Task-level JIT dependency-delivery preflights parsed from <c>tasks/&lt;id&gt;/preflights/</c>
    /// (design-of-record 09-preflight-first-class, SSOT §1/§4) — the sibling of the postcondition
    /// <see cref="Guardrails"/> folder, evaluated in the task's own segment worktree at <c>taskBase</c>
    /// BEFORE the attempt loop, to verify a producer actually delivered in the bytes this consumer
    /// inherited. Guardrail-shaped files (same shape and parser as <see cref="Guardrails"/>, opening with
    /// a <c>catches:</c> declaration). Empty when the folder is absent (the common case). The per-task
    /// preflight slot that runs these lands in a later deliverable.
    /// </summary>
    public IReadOnlyList<GuardrailDefinition> Preflights { get; init; } = [];

    /// <summary>
    /// When true, this task is the terminal integration gate for the plan (plan 08 M2, SSOT §3.3).
    /// A multi-leaf or fan-in plan must have exactly one such sink, which must carry at least one
    /// guardrail with <c>scope:"integration"</c>. Default false (no gate role).
    /// </summary>
    public bool IntegrationGate { get; init; }

    /// <summary>
    /// The declared write-scope for this task (plan 08 §2/§3.4, SSOT §3.4). Each entry is a
    /// glob pattern matched against <c>git diff --name-status</c> paths after the action runs.
    /// Null (absent in <c>task.json</c>) is the off-switch — no write-scope check runs.
    /// </summary>
    public IReadOnlyList<string>? WriteScope { get; init; }

    /// <summary>
    /// The declared staging outputs for autonomous <c>.claude/</c> delivery (SSOT §3.5, issue #130).
    /// Each entry maps a <c>from</c> path/glob (relative to <c>GUARDRAILS_STAGING_DIR</c>, where the
    /// action writes its deliverable) to a <c>to</c> destination under <c>.claude/</c> (where the
    /// harness moves it after the action succeeds and before guardrails run). Null (absent in
    /// <c>task.json</c>) means no staging — the unchanged default behavior. A present-but-malformed
    /// list is a validation error (<see cref="Loading.DiagnosticCodes.StagingOutputsInvalid"/>).
    /// </summary>
    public IReadOnlyList<StagingOutput>? StagingOutputs { get; init; }
}

/// <summary>
/// One <c>stagingOutputs[]</c> mapping (SSOT §3.5): the action writes its deliverable to
/// <see cref="From"/> (relative to the per-task staging root <c>GUARDRAILS_STAGING_DIR</c>), and the
/// harness moves it to <see cref="To"/> (a workspace-relative path under <c>.claude/</c>) after the
/// action succeeds and before guardrails run.
/// </summary>
public sealed record StagingOutput
{
    /// <summary>The source path or glob relative to the per-task staging root.</summary>
    public required string From { get; init; }

    /// <summary>The workspace-relative destination under <c>.claude/</c>.</summary>
    public required string To { get; init; }
}

namespace Guardrails.Core.Execution;

/// <summary>The result of running a single guardrail.</summary>
public sealed record GuardrailResult
{
    public required string Name { get; init; }
    public required bool Passed { get; init; }

    /// <summary>One-line actionable reason on failure (the guardrail's first stdout line), else null.</summary>
    public string? Reason { get; init; }

    /// <summary>
    /// The guardrail's full captured output on failure (stdout, or stderr when stdout is empty),
    /// for the retry feedback (issue #26 Gap 1). The one-line <see cref="Reason"/> truncates at
    /// the first line, which hid 8-of-9 build errors in a real failure; the retry agent needs
    /// every error, not just the first. Null for passing guardrails and prompt guardrails (whose
    /// signal is the one-line verdict reason).
    /// </summary>
    public string? Output { get; init; }
}

/// <summary>The full result of a single task in an M2 serial run.</summary>
public sealed record TaskResult
{
    public required string TaskId { get; init; }
    public required TaskOutcome Outcome { get; init; }

    /// <summary>The action's exit code, or null when the task was blocked and never ran.</summary>
    public int? ActionExitCode { get; init; }

    /// <summary>Guardrail results in execution order (empty if action failed or task was blocked).</summary>
    public IReadOnlyList<GuardrailResult> Guardrails { get; init; } = [];

    /// <summary>A short human-readable explanation of the outcome (for the summary and logs).</summary>
    public required string Summary { get; init; }

    /// <summary>
    /// In worktree mode, the path to the validated fragment file for deferred B1 settle in the
    /// Scheduler. Null in serial mode (AttemptJournaler handles the merge immediately).
    /// </summary>
    public string? FragmentPath { get; init; }

    /// <summary>
    /// True when the Scheduler must perform the B1 deferred settle (fragment merge → git commit →
    /// journal RecordSettle) for this result. Set by <see cref="AttemptJournaler.ValidateFragmentForSettle"/>
    /// in worktree mode. False in serial mode (AttemptJournaler already merged and journaled).
    /// </summary>
    public bool DeferredSettle { get; init; }

    /// <summary>
    /// In worktree mode, the not-yet-journaled attempt data the Scheduler's B1 settle records (issue
    /// #196): a succeeded worktree task must journal a real <see cref="Journal.AttemptRecord"/> — with
    /// the same shape serial mode records — TOGETHER with the reserved <c>mergeSequence</c>, so
    /// <c>journal.Tasks[id].Attempts</c> is non-empty for a succeeded task in BOTH modes (SSOT §7).
    /// The executor computes this per-attempt data (attempt number, timing, cost, relative log dir,
    /// and the #198 provenance) but cannot record it, because the settle (and thus the outcome +
    /// mergeSequence) is deferred to the Scheduler under the integration lock. Null in serial mode
    /// (AttemptJournaler already recorded the attempt) and for non-deferred results.
    /// </summary>
    public PendingAttempt? PendingAttempt { get; init; }

    /// <summary>True only for a genuine success this run (not a resume skip).</summary>
    public bool Succeeded => Outcome == TaskOutcome.Succeeded;

    /// <summary>
    /// True when this task is "green" for the run's overall verdict: it succeeded this run
    /// or was skipped because the journal already recorded it as succeeded (resume).
    /// </summary>
    public bool IsGreen => Outcome is TaskOutcome.Succeeded or TaskOutcome.Skipped;
}

/// <summary>
/// The per-attempt data a worktree-mode success carries to the Scheduler's B1 settle so it can journal
/// a real <see cref="Journal.AttemptRecord"/> alongside the reserved <c>mergeSequence</c> (issue #196).
/// The executor computes all of it during the attempt but defers the actual record because the outcome
/// (succeeded vs a non-FF-union rollback to needs-human) and the mergeSequence are only known after the
/// integration commit, under the integration lock. The settle path builds the AttemptRecord from these
/// fields — the SAME shape serial mode's <see cref="AttemptJournaler.CompleteSucceededOrInvalidFragment"/>
/// records — so a succeeded task has a populated <c>Attempts</c> list in BOTH modes.
/// </summary>
public sealed record PendingAttempt
{
    /// <summary>1-based attempt number (already reserved by the journal for this attempt's log dir).</summary>
    public required int Attempt { get; init; }

    /// <summary>UTC attempt start time.</summary>
    public required DateTimeOffset StartedAt { get; init; }

    /// <summary>The action's exit code (0 on the success path).</summary>
    public int? ActionExitCode { get; init; }

    /// <summary>The prompt attempt's total cost in USD (null for a script or an unreported prompt cost).</summary>
    public decimal? CostUsd { get; init; }

    /// <summary>This attempt's log dir, relative to the plan dir (SSOT §7/§8).</summary>
    public required string LogDir { get; init; }

    /// <summary>
    /// The #198 provenance the harness knew at attempt launch (resolved model, segment worktree,
    /// base commit). Never null in worktree mode (the segment always exists); the model is null for
    /// a script task.
    /// </summary>
    public Journal.AttemptProvenance? Provenance { get; init; }
}

/// <summary>The aggregate result of an entire run.</summary>
public sealed record RunReport
{
    /// <summary>Per-task results in plan order.</summary>
    public required IReadOnlyList<TaskResult> Tasks { get; init; }

    /// <summary>True when the run was cancelled (Ctrl+C) before quiescence.</summary>
    public bool Cancelled { get; init; }

    /// <summary>True when every task is green (succeeded this run or skipped as already-succeeded).</summary>
    public bool AllSucceeded => Tasks.All(t => t.IsGreen);

    /// <summary>True when at least one task failed or was blocked.</summary>
    public bool AnyFailed => Tasks.Any(t => !t.IsGreen);

    /// <summary>
    /// The outcome of the end-of-run merge-on-success delivery (plan 08 SSOT §5.3).
    /// Null when <c>mergeOnSuccess</c> is false or the run was not wholly green.
    /// Implemented by task 22.
    /// </summary>
    public MergeOnSuccessResult? MergeOnSuccessOutcome { get; init; }

    /// <summary>
    /// Free-text detail for the merge-on-success outcome when it carries one — specifically the git
    /// hook's stderr when <see cref="MergeOnSuccessOutcome"/> is
    /// <see cref="MergeOnSuccessResult.HookRejected"/> (issues #149/#150). Null otherwise. The CLI
    /// renders this verbatim so the user sees exactly why their hook rejected the user-branch merge.
    /// </summary>
    public string? MergeOnSuccessDetail { get; init; }

    /// <summary>
    /// Non-null when the run was ABORTED by an unexpected infrastructure fault (a task executor or an
    /// integration step threw — e.g. an offline git hook failing an INTERNAL commit, or git itself
    /// being unavailable). Rather than propagating an unhandled exception out of the scheduler
    /// (issue #150), the run terminates the worker pool, runs the end-of-run cleanup sweep, and
    /// returns a report carrying this reason. The CLI renders a one-line diagnostic + remedy, writes
    /// the FULL exception to the run logs, and exits non-zero — an honest halt, never a raw stack
    /// trace as the headline. When set, treat the run as failed regardless of per-task outcomes.
    /// </summary>
    public RunAbort? Abort { get; init; }

    /// <summary>True when the run was aborted by an infrastructure fault (see <see cref="Abort"/>).</summary>
    public bool Aborted => Abort is not null;
}

/// <summary>
/// Carries why a run was aborted by an unexpected infrastructure fault (issue #150). The
/// <see cref="Headline"/> is the one-line human diagnostic the CLI shows; <see cref="Detail"/>
/// is the full exception text written to the run logs (a dev tool keeps the detail — just not as
/// the headline). <see cref="Remedy"/> is an actionable next step.
/// </summary>
public sealed record RunAbort
{
    /// <summary>One-line, human-readable summary of what went wrong (the console headline).</summary>
    public required string Headline { get; init; }

    /// <summary>An actionable next step for the human (e.g. "run git online", "fix the hook").</summary>
    public required string Remedy { get; init; }

    /// <summary>The full fault text (typically the exception's ToString()) for the run logs.</summary>
    public required string Detail { get; init; }
}

namespace Guardrails.Core.Execution;

/// <summary>Terminal outcome of a single task in a serial run.</summary>
public enum TaskOutcome
{
    /// <summary>Action exited 0, every guardrail passed, and the fragment (if any) merged.</summary>
    Succeeded,

    /// <summary>The action exited non-zero (guardrails were skipped).</summary>
    ActionFailed,

    /// <summary>The action succeeded but one or more guardrails failed.</summary>
    GuardrailFailed,

    /// <summary>The action and guardrails passed but the action's fragment was not a valid JSON object (SSOT §6.2).</summary>
    InvalidFragment,

    /// <summary>
    /// A prompt action signalled <c>needsHuman</c> in its fragment (SSOT §9): the harness
    /// escalates to a human immediately, with no retry burn and no guardrails.
    /// </summary>
    NeedsHuman,

    /// <summary>
    /// A transient infrastructure limit (429/503/529, "overloaded", a usage/session/rate limit) did
    /// not clear within the pause budget (issue #115/#190): the harness settles the task straight to
    /// this DISTINCT outcome rather than the generic <see cref="NeedsHuman"/> — "re-run later", not a
    /// task defect to debug. Unlike <see cref="TransientPause"/> (below), this value IS journaled
    /// (as <c>JournalTaskStatus.NeedsHuman</c> — see the note on <see cref="AttemptJournaler.RateLimitExhausted"/>
    /// for why the JOURNAL status stays <c>needs-human</c> while only this in-memory/per-run
    /// <see cref="TaskOutcome"/> distinguishes the reason) and IS reported to the observer's
    /// <c>TaskFinished</c> and to <see cref="RunReport"/> — it is the per-run/UI-facing rendering of a
    /// rate-limit halt, not an ephemeral pause signal.
    /// </summary>
    RateLimited,

    /// <summary>A dependency did not succeed, so this task never ran.</summary>
    Blocked,

    /// <summary>Resume skipped this task because the journal already records it as succeeded.</summary>
    Skipped,

    /// <summary>The run was cancelled before this task could finish (or start). Journaled pending; resume re-runs it.</summary>
    Cancelled,

    /// <summary>
    /// An IN-MEMORY-ONLY signal (issue #115): the attempt hit a transient, retryable infrastructure
    /// condition (HTTP 429/503/529, "overloaded", a usage/session/rate limit). The attempt loop in
    /// <see cref="TaskExecutor"/> backs off and re-runs the SAME attempt WITHOUT consuming the retry
    /// budget. This value is NEVER journaled, never reported to the observer's <c>TaskFinished</c>,
    /// and never appears in a <see cref="RunReport"/>; it only travels between
    /// <see cref="TaskExecutor"/>'s attempt method and its loop.
    /// </summary>
    TransientPause
}

}

/// <summary>
/// The task-id → plan-relative folder path map <see cref="HtmlDiagramRenderer"/> needs to inject
/// the title-band click overlay (see class remarks, issue #235): a task container's click target
/// is no longer a Mermaid-source mechanism, so this is how the same path data
/// <see cref="AppendClickDirectives"/> used to feed the removed anchor's <c>click href</c> now
/// reaches the post-render JavaScript instead — as a small embedded JSON side-table keyed by the
/// SAME container id (<c>task_&lt;base&gt;</c>) <see cref="AppendTaskContainer"/> emits, so the
/// overlay script can look a cluster's target up by its own DOM id. Plan-relative, forward-slash
/// paths (not OS separators, not absolute) for the same byte-identical-across-OSes reason as
/// <see cref="ToPlanRelative"/>.
/// </summary>
public static IReadOnlyDictionary<string, string> TaskFolderTargets(PlanDefinition plan)
{
    ArgumentNullException.ThrowIfNull(plan);

    List<TaskNode> tasks = plan.Tasks.OrderBy(t => t.Id, StringComparer.Ordinal).ToList();
    IReadOnlyDictionary<string, string> nodeIdBase = AllocateNodeIdBases(tasks);

    var targets = new Dictionary<string, string>(StringComparer.Ordinal);
    foreach (TaskNode task in tasks)
    {
        string containerId = $"task_{nodeIdBase[task.Id]}";
        targets[containerId] = ToPlanRelative(plan.PlanDirectory, task.Directory) + "/";
    }

    return targets;
}

/// <summary>
/// The cosmetic <c>classDef</c> lines (colors) for the LEAF check nodes — preflight check
/// and guardrail check — which reference them inline via <c>:::preflight</c>/<c>:::guardrail</c>.
/// The task-container and plan-level-container fills are applied per-container by a
/// <c>style &lt;id&gt; …</c> statement instead (see <see cref="TaskStyle"/> /
/// <see cref="PlanLevelStyle"/>), because a <c>class</c> assignment does not reach a subgraph
/// that is an edge endpoint in the bundled Mermaid. Shared by <see cref="Render"/> and
/// <see cref="RenderInteractive"/>; deliberately EXCLUDED from the staleness key (see
/// <see cref="SemanticContent"/>), which is why <see cref="SemanticContent"/> does not call it.
/// No longer emits an <c>invisible</c> classDef (issue #211's anchor-node mechanism was removed
/// entirely — issue #235; see class remarks): the task-container click target is now a
/// post-render SVG overlay <see cref="HtmlDiagramRenderer"/> injects via JavaScript, not a
/// Mermaid node/class at all.
/// </summary>
private static void AppendClassDefs(StringBuilder sb)
{
    AppendLf(sb, "  classDef preflight fill:#e6d7ff,stroke:#6f42c1,color:#2e1065;");
    AppendLf(sb, "  classDef guardrail fill:#fff3cd,stroke:#b8860b,color:#3d2c00;");
}

/// <summary>
/// The SEMANTIC content of the diagram: ONLY the containers + nested checks + container edges
/// (with their drawn labels), with NO <c>flowchart TD</c> header and NO cosmetic
/// <c>classDef</c> color definitions. This is what <see cref="GraphSourceHash"/> hashes, so
/// the staleness key tracks exactly what the diagram DRAWS (container membership, nested
/// check labels, DAG shape) — including the PLAN-LEVEL <c>preflights/</c>/<c>guardrails/</c>
/// folder checks, not just <c>tasks{}</c>, so editing a Terminal Gate check moves the hash
/// too. Shares the single <see cref="AppendNodesAndEdges"/> emitter with <see cref="Render"/>,
/// so the two can never drift.
/// </summary>
internal static string SemanticContent(PlanDefinition plan)
{
    ArgumentNullException.ThrowIfNull(plan);

    var sb = new StringBuilder();
    AppendNodesAndEdges(plan, sb);
    return sb.ToString();
}

/// <summary>
/// Append the container model (the semantic content) for the plan: the plan-level Full Flight
/// Checks container, one container per task in ordinal order, the plan-level Terminal Gate
/// container, and finally every container→container edge. The single shared emitter behind
/// <see cref="Render"/>, <see cref="SemanticContent"/>, and <see cref="RenderInteractive"/> —
/// all three now emit the IDENTICAL container/node shape (issue #235 removed the interactive-only
/// anchor node), so <see cref="Render"/> and <see cref="RenderInteractive"/> differ ONLY in
/// whether <c>click</c> directives for CHECK nodes are appended afterward. Returns the
/// task-id → node-id-base map so the caller can emit click directives against the SAME node ids
/// (the emitted bytes are unchanged whether or not the caller uses the return value).
/// </summary>
/// <remarks>
/// ORDER MATTERS: every container is emitted (fully, including its <c>end</c>) BEFORE any
/// container→container edge line. A <c>subgraph A --&gt; subgraph B</c> edge references the two
/// container ids, so both subgraph blocks must already be declared; emitting all containers
/// first keeps every edge's endpoints resolvable and the output deterministic.
/// </remarks>
private static IReadOnlyDictionary<string, string> AppendNodesAndEdges(PlanDefinition plan, StringBuilder sb)
{
    var graph = new DependencyGraph(plan.Tasks);

    // Ordinal task order throughout (repo convention).
    List<TaskNode> tasks = plan.Tasks
        .OrderBy(t => t.Id, StringComparer.Ordinal)
        .ToList();

    // Allocate an injective node-id base per task ONCE, in ordinal order: a task whose
    // sanitized id collides with an earlier one gets a deterministic _2, _3, … suffix.
    IReadOnlyDictionary<string, string> nodeIdBase = AllocateNodeIdBases(tasks);

    // --- plan-level "Full Flight Checks" container (top, ALWAYS emitted) -----------
    AppendPlanLevelContainer(sb, PlanPreflightsId, "Full Flight Checks", plan.PlanPreflights, "preflight");

    // --- one container per task ------------------------------------------------------
    foreach (TaskNode task in tasks)
    {
        AppendTaskContainer(sb, task, nodeIdBase[task.Id]);
    }

    // --- plan-level "Terminal Gate" container (bottom, ALWAYS emitted) --------------
    AppendPlanLevelContainer(sb, PlanGuardrailsId, "Terminal Gate", plan.PlanGuardrails, "guardrail");

    // --- container→container edges (every container above is already fully declared) -----
    AppendContainerEdges(graph, tasks, nodeIdBase, sb);

    return nodeIdBase;
}

/// <summary>
/// Append a plan-level bracket container (<c>plan_preflights</c> or <c>plan_guardrails</c>):
/// its checks (sorted ordinal by name) as small boxes inside, styled with
/// <paramref name="checkClass"/>. ALWAYS emitted, even when <paramref name="checks"/> is empty
/// — the two plan-level containers are structural brackets on the whole DAG, not conditional
/// content. The DAG edge attaches to this container's own subgraph id (no interior anchor).
/// </summary>
private static void AppendPlanLevelContainer(
    StringBuilder sb,
    string containerId,
    string label,
    IReadOnlyList<GuardrailDefinition> checks,
    string checkClass)
{
    AppendLf(sb, $"  subgraph {containerId}[{Quote(label)}]");
    AppendCheckNodes(sb, "    ", $"{containerId}", checks, checkClass);
    AppendLf(sb, "  end");
    AppendLf(sb, $"  style {containerId} {PlanLevelStyle}");
}

/// <summary>
/// Append one task container: its preflight leaf check node(s) (if any), THEN its guardrail
/// leaf check node(s) — both DIRECTLY inside the container, with no nested
/// <c>Preflights</c>/<c>Guardrails</c> wrapper subgraph (see class remarks, "Nested boxes
/// dropped") — then the container's <c>style</c> fill. The DAG edge attaches to this
/// container's own subgraph id (no interior anchor).
/// </summary>
/// <remarks>
/// <b>Emission-order contract (load-bearing, tested):</b> preflight check nodes are ALWAYS
/// emitted before guardrail check nodes within a container. This is not a rendering accident —
/// with the nested boxes gone, source order is the only surviving signal that preflights run
/// BEFORE the task's attempt loop and guardrails run AFTER it, so callers (and the legend) may
/// rely on it as a stable convention.
/// </remarks>
/// <remarks>
/// No anchor node of any kind is emitted here (issue #211's mechanism was removed entirely —
/// issue #235; see class remarks). <see cref="Render"/> and <see cref="RenderInteractive"/> now
/// emit byte-identical container/node shape for every task; the container's click target lives
/// entirely in <see cref="HtmlDiagramRenderer"/>'s post-render JavaScript overlay instead.
/// </remarks>
private static void AppendTaskContainer(StringBuilder sb, TaskNode task, string @base)
{
    string containerId = $"task_{@base}";

    AppendLf(sb, $"  subgraph {containerId}[{Quote(task.Id)}]");

    // Preflights BEFORE guardrails — see remarks: this order is the emission-order contract
    // that now carries the "before the attempt loop" / "after the action" temporal semantic
    // the removed nested boxes used to convey visually.
    AppendCheckNodes(sb, "    ", $"{containerId}_pf", task.Preflights, "preflight");
    AppendCheckNodes(sb, "    ", $"{containerId}_gr", task.Guardrails, "guardrail");

    AppendLf(sb, "  end");
    AppendLf(sb, $"  style {containerId} {TaskStyle}");
}

/// <summary>
/// Append <paramref name="checks"/> (sorted ordinal by name, for input-order independence) as
/// <c>{nodeIdPrefix}_{ordinal}[label]:::{checkClass}</c> node lines, one per check. Drawn label
/// is ALWAYS <see cref="GuardrailDefinition.Name"/> — the check's own short, stable identifier
/// (the file-derived name, e.g. <c>01-core-tests-green-excluding-target</c>), never the
/// (possibly long) <see cref="GuardrailDefinition.Description"/>. A prior version drew the
/// description (truncated for task-level preflights only, issue #211) — the owner asked
/// instead for the same short, meaningful identifier every box's click target already opens,
/// uniformly for every check kind at both scopes (issue #222). The full description remains
/// reachable via the node's <c>click</c> tooltip in <see cref="RenderInteractive"/> (issue
/// #33's existing click mechanism, unaffected by this change) — no truncation heuristic is
/// needed anywhere now.
/// </summary>
private static void AppendCheckNodes(
    StringBuilder sb,
    string indent,
    string nodeIdPrefix,
    IReadOnlyList<GuardrailDefinition> checks,
    string checkClass)
{
    int ordinal = 0;
    foreach (GuardrailDefinition check in checks.OrderBy(c => c.Name, StringComparer.Ordinal))
    {
        AppendLf(sb, $"{indent}{nodeIdPrefix}_{ordinal}[{Quote(check.Name)}]:::{checkClass}");
        ordinal++;
    }
}

/// <summary>
/// Append every container→container edge: the plan-preflights container into each DAG ROOT
/// task's container (a task with no <c>dependsOn</c>), one edge per <c>dependsOn</c>
/// relationship between two task containers, and each DAG LEAF task's container (a task nothing
/// depends on) into the plan-guardrails container. The edge references the container's own
/// subgraph id, so Mermaid clips the arrow to the container's OUTER BORDER (issue #210). A
/// task-level preflight does not change this — the gated dependency edge is drawn exactly like
/// any other; the preflight is only ever a check node inside the consumer's own container
/// (emitted before the container's guardrail check nodes — see <see cref="AppendTaskContainer"/>).
/// </summary>
private static void AppendContainerEdges(
    DependencyGraph graph,
    IReadOnlyList<TaskNode> tasks,
    IReadOnlyDictionary<string, string> nodeIdBase,
    StringBuilder sb)
{
    foreach (TaskNode root in tasks.Where(t => t.DependsOn.Count == 0))
    {
        AppendLf(sb, $"  {PlanPreflightsId} --> task_{nodeIdBase[root.Id]}");
    }

    foreach (TaskNode dependency in tasks)
    {
        foreach (string dependentId in graph.DependentsOf(dependency.Id)
                     .OrderBy(id => id, StringComparer.Ordinal))
        {
            AppendLf(sb, $"  task_{nodeIdBase[dependency.Id]} --> task_{nodeIdBase[dependentId]}");
        }
    }

    foreach (TaskNode leaf in tasks.Where(t => graph.DependentsOf(t.Id).Count == 0))
    {
        AppendLf(sb, $"  task_{nodeIdBase[leaf.Id]} --> {PlanGuardrailsId}");
    }
}

/// <summary>
/// Append <c>click</c> directives (HTML-viewer only; see <see cref="RenderInteractive"/>) for
/// every CHECK node — plan-level or task-level, preflight or guardrail — opening its own file
/// as a plan-relative, forward-slash <c>file://</c> target resolved relative to
/// <c>diagram.html</c> at the plan root, opened in a new tab (<c>_blank</c>) so the diagram
/// stays put. Emitted in the same ordinal/sorted order as the nodes for determinism, and using
/// the SAME node-id scheme as <see cref="AppendNodesAndEdges"/> so every click target actually
/// exists. A task-level preflight's click tooltip carries its FULL description (not just its
/// name) since <see cref="AppendCheckNodes"/> draws only a truncated label for it — the
/// tooltip is the click-for-detail mechanism that keeps the full text from being lost.
/// </summary>
/// <remarks>
/// <b>No container click directive is emitted here (issue #235).</b> A task container's click
/// target is no longer a Mermaid mechanism at all — see class remarks, "A task container's click
/// target is a POST-RENDER SVG overlay...". <see cref="HtmlDiagramRenderer"/> injects it via
/// JavaScript after Mermaid's render completes, using <see cref="TaskFolderTargets"/> for the
/// folder path data. Leaf check-node clicks are unaffected here: they still target the leaf node
/// itself, which Mermaid DOES wrap in a real clickable <c>&lt;a href&gt;</c>.
/// </remarks>
private static void AppendClickDirectives(
    PlanDefinition plan, IReadOnlyDictionary<string, string> nodeIdBase, StringBuilder sb)
{
    AppendCheckClicks(plan, plan.PlanPreflights, PlanPreflightsId, sb);

    foreach (TaskNode task in plan.Tasks.OrderBy(t => t.Id, StringComparer.Ordinal))
    {
        string @base = nodeIdBase[task.Id];
        string containerId = $"task_{@base}";

        if (task.Preflights.Count > 0)
        {
            AppendCheckClicks(plan, task.Preflights, $"{containerId}_pf", sb);
        }

        AppendCheckClicks(plan, task.Guardrails, $"{containerId}_gr", sb);
    }

    AppendCheckClicks(plan, plan.PlanGuardrails, PlanGuardrailsId, sb);
}

/// <summary>
/// Append one <c>click</c> directive per check in <paramref name="checks"/> (sorted ordinal by
/// name, mirroring <see cref="AppendCheckNodes"/> exactly so the ordinal-suffixed node id each
/// click targets is the one actually emitted for that check). The tooltip is ALWAYS
/// <c>Description ?? Name</c> in full, for every check kind at both scopes — since the drawn
/// label is now always the short <c>Name</c> (issue #222), the tooltip is the one place the
/// full description lives; there is no longer a "some checks get the full text, others don't"
/// distinction.
/// </summary>
private static void AppendCheckClicks(
    PlanDefinition plan,
    IReadOnlyList<GuardrailDefinition> checks,
    string nodeIdPrefix,
    StringBuilder sb)
{
    int ordinal = 0;
    foreach (GuardrailDefinition check in checks.OrderBy(c => c.Name, StringComparer.Ordinal))
    {
        string checkPath = ToPlanRelative(plan.PlanDirectory, check.Path);
        string tooltipText = string.IsNullOrWhiteSpace(check.Description) ? check.Name : check.Description!;
        AppendLf(sb, $"  click {nodeIdPrefix}_{ordinal} href \"{checkPath}\" \"{ClickTooltip(tooltipText)}\" _blank");
        ordinal++;
    }

