43	    public async Task SettledRun_LeavesDiagramHtml_WithoutLiveStatus_ComposingRootGap()
44	    {
45	        using var plan = new ScriptPlanBuilder()
46	            .AddTask("01-first")
47	            .AddTask("02-second", true, true, "01-first");
48	
