55	        Assert.True(File.Exists(htmlPath), "guardrails graph must write diagram.html before the run");
56	
57	        int runExit = await RunCliAsync("run", plan.PlanDir, "--no-ui", "--no-log-server");
58	        Assert.Equal(ExitCodes.Success, runExit);
59	
60	        string html = await File.ReadAllTextAsync(htmlPath, TestContext.Current.CancellationToken);
61	
62	        // The settled outcome must be reflected: the task known to have succeeded shows "passed" in the
63	        // embedded #node-statuses side-table (HtmlDiagramRenderer's optional nodeStatuses parameter). RED
64	        // today — nothing wires OnTheFlyDiagramObserver into RunCommand, so this side-table is never
65	        // present at all; diagram.html is exactly the plain graph render written above.
66	        IReadOnlyDictionary<string, string> nodeStatuses = ReadNodeStatuses(html);
