using System.CommandLine;
using System.Text.Json;
using Guardrails.Cli;

namespace Guardrails.Integration.Tests;

/// <summary>
/// The composition-root wiring test for the live diagram (issue #120 doctrine). <c>OnTheFlyDiagramObserver</c>
/// (04-implement-diagram-observer) is implemented and independently unit-tested, but nothing in
/// <c>Guardrails.Cli.Commands.RunCommand</c> constructs or injects it yet — so a REAL <c>guardrails run</c>
/// never actually calls it, and a plan's <c>diagram.html</c> never reflects the run's progress or its settled
/// outcome. This drives the real CLI end-to-end (mirroring <c>PlanGuardrailPhaseTests</c>' <c>CommandFactory
/// .BuildRootCommand</c> + <see cref="StringConsoleIo"/> pattern) against a small script-only plan, then reads
/// the generated <c>diagram.html</c> off disk.
/// <para>
/// A real plan already carries <c>diagram.html</c> BEFORE it is ever run — <c>/plan-breakdown</c> writes it
/// once via <c>guardrails graph</c> (<c>Guardrails.Core.Breakdown.BreakdownManifest</c>). This fixture
/// reproduces exactly that starting state: an explicit <c>graph</c> invocation writes the plain static render
/// (no per-node status at all) BEFORE <c>run</c> ever executes.
/// </para>
/// <para>
/// RED on current code: <c>run</c> never touches <c>diagram.html</c>, so after a wholly-green run it is left
/// byte-for-byte the static render <c>graph</c> wrote above — no <c>#node-statuses</c> side-table at all, so
/// the settled-status assertion below fails. That failure is exactly the TDD red
/// <c>06-wire-diagramobserver-into-runcommand</c> turns green, by constructing <c>OnTheFlyDiagramObserver</c>
/// during the run AND adding a final, non-refreshing export at run end (mirroring <c>RunCommand</c>'s existing
/// <c>LogSiteRenderer.ExportSite</c> call for the analogous log site). This test deliberately does NOT
/// construct <c>OnTheFlyDiagramObserver</c> itself, and does NOT hand-wire the scheduler with it pre-injected
/// — either would make the test pass even though production code never wires it, which is exactly the
/// false-green issue #120 warns against.
/// </para>
/// </summary>
public sealed class DiagramLiveStatusWiringTests
{
    private static async Task<int> RunCliAsync(params string[] args)
    {
        var io = new StringConsoleIo();
        RootCommand root = CommandFactory.BuildRootCommand(io);
        return await root.Parse(args).InvokeAsync();
    }

    [Fact]
    public async Task SettledRun_LeavesDiagramHtml_WithoutLiveStatus_ComposingRootGap()
    {
        using var plan = new ScriptPlanBuilder()
            .AddTask("01-first")
            .AddTask("02-second", true, true, "01-first");

        // Reproduce the real starting state: a plan's diagram.html already exists (written once by
        // /plan-breakdown via `guardrails graph`) before the plan is ever run.
        int graphExit = await RunCliAsync("graph", plan.PlanDir);
        Assert.Equal(ExitCodes.Success, graphExit);

        string htmlPath = Path.Combine(plan.PlanDir, "diagram.html");
        Assert.True(File.Exists(htmlPath), "guardrails graph must write diagram.html before the run");

        int runExit = await RunCliAsync("run", plan.PlanDir, "--no-ui", "--no-log-server");
        Assert.Equal(ExitCodes.Success, runExit);

        string html = await File.ReadAllTextAsync(htmlPath, TestContext.Current.CancellationToken);

        // The settled outcome must be reflected: the task known to have succeeded shows "passed" in the
        // embedded #node-statuses side-table (HtmlDiagramRenderer's optional nodeStatuses parameter). RED
        // today — nothing wires OnTheFlyDiagramObserver into RunCommand, so this side-table is never
        // present at all; diagram.html is exactly the plain graph render written above.
        IReadOnlyDictionary<string, string> nodeStatuses = ReadNodeStatuses(html);
        Assert.Equal("passed", nodeStatuses.GetValueOrDefault("task_01_first"));

        // Independent of the above: the FINAL, post-run diagram.html must be fully static — no
        // auto-refresh meta tag (mirrors LogSiteRenderer's during-run-vs-final duality; a run-end export
        // that forgot the final, non-refreshing render would leave this refreshing forever).
        Assert.DoesNotContain("<meta http-equiv=\"refresh\"", html, StringComparison.Ordinal);
    }

    /// <summary>
    /// Extract the <c>#node-statuses</c> JSON side-table <c>HtmlDiagramRenderer</c> embeds only when a live
    /// status map is supplied. Absent entirely on the plain <c>graph</c> render, which is exactly the RED
    /// signal this test relies on.
    /// </summary>
    private static IReadOnlyDictionary<string, string> ReadNodeStatuses(string html)
    {
        const string marker = "<script type=\"application/json\" id=\"node-statuses\">";
        int start = html.IndexOf(marker, StringComparison.Ordinal);
        Assert.True(start >= 0,
            "diagram.html has no #node-statuses side-table — nothing wires a live status observer into " +
            "RunCommand yet (issue #120 composition-root gap).");

        start += marker.Length;
        int end = html.IndexOf("</script>", start, StringComparison.Ordinal);
        Assert.True(end >= 0, "malformed #node-statuses script tag in diagram.html");

        string json = html[start..end];
        return JsonSerializer.Deserialize<Dictionary<string, string>>(json) ?? new Dictionary<string, string>();
    }
}

