using Guardrails.Core.Execution;
using Guardrails.Core.Model;

namespace Guardrails.Cli.Ui;

/// <summary>
/// A decorator <see cref="IRunObserver"/> that keeps <c>diagram.html</c>'s live per-node status
/// overlay (<c>HtmlDiagramRenderer</c>'s optional <c>nodeStatuses</c> parameter, issue #219) up to
/// date as the run proceeds. Mirrors <see cref="OnTheFlyLogSiteObserver"/>'s shape exactly: it
/// WRAPS the real observer, forwards every event verbatim, and AFTER forwarding re-renders
/// <c>diagram.html</c> from an in-memory per-node status map:
/// <list type="bullet">
///   <item>On <see cref="TaskStarting"/> the task's own container flips to <c>running</c>.</item>
///   <item>On <see cref="GuardrailFinished"/> that SPECIFIC guardrail's leaf node (not the whole
///     task) flips to <c>passed</c>/<c>failed</c>.</item>
///   <item>On <see cref="TaskFinished"/> the task's container flips to its settled outcome.</item>
/// </list>
///
/// <para>
/// <b>Mermaid source / hash / task-folder-targets are threaded via the constructor</b>, not
/// re-read from the already-written <c>diagram.html</c>: the observer has no direct access to the
/// <c>PlanDefinition</c> the CLI's <c>graph</c> command used to generate it, and re-parsing the
/// emitted HTML back out would be strictly more code (and more fragile — a template change could
/// silently break the parse) than simply carrying the three values the constructor already has at
/// hand when the run starts.
/// </para>
///
/// <para>
/// <b>Node-id resolution.</b> A task's container id (<c>task_&lt;base&gt;</c>) is recovered from
/// the constructor-supplied <c>taskFolderTargets</c> map (<c>MermaidRenderer.TaskFolderTargets</c>)
/// by matching its plan-relative folder path's LAST segment against <see cref="TaskNode.Id"/> — the
/// task id IS the folder name (see <see cref="TaskNode.Id"/>'s own doc comment), so this recovers
/// the exact id <c>MermaidRenderer</c> emitted without duplicating its private
/// sanitize/disambiguate algorithm here. A guardrail's leaf id (<c>task_&lt;base&gt;_gr_&lt;n&gt;</c>)
/// is then the container id plus the guardrail's ordinal position in <see cref="TaskNode.Guardrails"/>
/// sorted ordinal by name — the SAME order <c>MermaidRenderer</c> emits the leaf nodes in.
/// </para>
///
/// <para>
/// This decorator does not track per-check preflight granularity: <see cref="IRunObserver"/> has no
/// per-preflight-check event (preflights settle as one aggregate re-verify result — see
/// <c>TaskExecutor</c>), so a task's preflight leaves are left at whatever status the diagram's
/// static <c>graph</c> render gave them; only the task container and its GUARDRAIL leaves get live
/// updates here.
/// </para>
///
/// <para>The status map is the only shared mutable state, and M4 worker threads call in
/// concurrently, so all access to it — and the render that projects from it — is serialised under
/// one lock. Renders are best-effort: a render failure (e.g. a transient file lock) is swallowed so
/// a UX nicety never flips a task's outcome or aborts the run — see <see cref="TryRender"/>.</para>
/// </summary>
public sealed class OnTheFlyDiagramObserver : IRunObserver
{
    private readonly IRunObserver _inner;
    private readonly IReadOnlyDictionary<string, TaskNode> _tasksById;
    private readonly string _diagramHtmlPath;
    private readonly string _mermaidSource;
    private readonly string _sourceHash;
    private readonly IReadOnlyDictionary<string, string> _taskFolderTargets;

    // Per-node status word (task containers + guardrail leaves), mutated and projected under one
    // lock — events arrive from concurrent M4 workers, and the render reads the whole map, so the
    // two must not race. Starts empty: unlike OnTheFlyLogSiteObserver there is no all-pending
    // initial write here — the plain `graph`-rendered diagram.html already on disk is the starting
    // state (DiagramLiveStatusWiringTests), and a node absent from the map simply gets no badge
    // (HtmlDiagramRenderer's overlay script skips ids it finds no status for).
    private readonly object _gate = new();
    private readonly Dictionary<string, string> _statusByNode = new(StringComparer.Ordinal);

    /// <param name="inner">The real observer every event is forwarded to (live or console).</param>
    /// <param name="tasks">
    /// The plan's tasks — used to resolve a settling task id back to its <see cref="TaskNode"/> (for
    /// its container id and <see cref="TaskNode.Guardrails"/> ordinal) on <see cref="TaskFinished"/>.
    /// </param>
    /// <param name="diagramHtmlPath">Absolute path to the plan's <c>diagram.html</c> to rewrite.</param>
    /// <param name="mermaidSource">
    /// The exact Mermaid text rendered into <c>diagram.md</c>/<c>diagram.html</c>
    /// (<c>HtmlDiagramRenderer.Render</c>'s <c>mermaidSource</c> argument).
    /// </param>
    /// <param name="sourceHash">The Mermaid source's <c>source-sha256</c> provenance stamp.</param>
    /// <param name="taskFolderTargets">
    /// The task-container-id → plan-relative-folder-path map (<c>MermaidRenderer.TaskFolderTargets</c>)
    /// — also used here to resolve a task's container id (see class remarks).
    /// </param>
    public OnTheFlyDiagramObserver(
        IRunObserver inner,
        IReadOnlyList<TaskNode> tasks,
        string diagramHtmlPath,
        string mermaidSource,
        string sourceHash,
        IReadOnlyDictionary<string, string> taskFolderTargets)
    {
        _inner = inner ?? throw new ArgumentNullException(nameof(inner));
        ArgumentNullException.ThrowIfNull(tasks);
        _tasksById = tasks.ToDictionary(t => t.Id, StringComparer.Ordinal);
        _diagramHtmlPath = diagramHtmlPath ?? throw new ArgumentNullException(nameof(diagramHtmlPath));
        _mermaidSource = mermaidSource ?? throw new ArgumentNullException(nameof(mermaidSource));
        _sourceHash = sourceHash ?? throw new ArgumentNullException(nameof(sourceHash));
        _taskFolderTargets = taskFolderTargets ?? throw new ArgumentNullException(nameof(taskFolderTargets));
    }

    public void TaskStarting(TaskNode task)
    {
        _inner.TaskStarting(task);
        SetStatus(ContainerId(task), "running");
        RenderDiagram();
    }

    public void AttemptStarting(TaskNode task, int attempt, int budget) =>
        _inner.AttemptStarting(task, attempt, budget);

    public void GuardrailFinished(TaskNode task, GuardrailResult result)
    {
        _inner.GuardrailFinished(task, result);
        SetStatus(GuardrailLeafId(task, result), result.Passed ? "passed" : "failed");
        RenderDiagram();
    }

    public void TaskFinished(TaskResult result)
    {
        _inner.TaskFinished(result);

        if (_tasksById.TryGetValue(result.TaskId, out TaskNode? task))
        {
            SetStatus(ContainerId(task), StatusWord(result.Outcome));
        }

        RenderDiagram();
    }

    public void PlanHashMismatch(string previousPlanHash) => _inner.PlanHashMismatch(previousPlanHash);

    public void ParallelismClampedNoProvider(int requested) => _inner.ParallelismClampedNoProvider(requested);

    public void CleanupFailed(string owner, Exception error) => _inner.CleanupFailed(owner, error);

    public void PromptPaused(TaskNode task, string reason, TimeSpan backoff, int pauseCount) =>
        _inner.PromptPaused(task, reason, backoff, pauseCount);

    // --- node-id resolution + diagram projection --------------------------------------------

    /// <summary>
    /// Recover a task's Mermaid container id (<c>task_&lt;base&gt;</c>) from the constructor-supplied
    /// <c>taskFolderTargets</c> map by matching its plan-relative folder path's last segment against
    /// <see cref="TaskNode.Id"/> (see class remarks).
    /// </summary>
    private string ContainerId(TaskNode task)
    {
        foreach ((string containerId, string folderPath) in _taskFolderTargets)
        {
            string trimmed = folderPath.TrimEnd('/');
            int slash = trimmed.LastIndexOf('/');
            string lastSegment = slash >= 0 ? trimmed[(slash + 1)..] : trimmed;
            if (string.Equals(lastSegment, task.Id, StringComparison.Ordinal))
            {
                return containerId;
            }
        }

        throw new InvalidOperationException(
            $"No task-folder-targets entry maps to task '{task.Id}' — the diagram was generated from a different plan.");
    }

